css:
/* Editorial desk. Re-theme with --acm-editor-paper, -ink, -accent and -warn; every tint,
   rule and hover below is mixed from those four. */
@property --acm-editor-p { syntax: '<number>'; inherits: true; initial-value: 0; }

.acm-editor {
  --acm-editor-paper: oklch(0.975 0.008 85);
  --acm-editor-ink: oklch(0.25 0.02 62);
  --acm-editor-accent: oklch(0.47 0.095 158);
  --acm-editor-warn: oklch(0.55 0.16 32);

  --acm-editor-card: color-mix(in oklch, white 65%, var(--acm-editor-paper));
  --acm-editor-sunk: color-mix(in oklch, var(--acm-editor-ink) 4%, var(--acm-editor-paper));
  --acm-editor-muted: color-mix(in oklch, var(--acm-editor-ink) 64%, var(--acm-editor-paper));
  --acm-editor-faint: color-mix(in oklch, var(--acm-editor-ink) 40%, var(--acm-editor-paper));
  --acm-editor-rule: color-mix(in oklch, var(--acm-editor-ink) 10%, transparent);
  --acm-editor-rule2: color-mix(in oklch, var(--acm-editor-ink) 18%, transparent);
  --acm-editor-hover: color-mix(in oklch, var(--acm-editor-ink) 5%, transparent);
  --acm-editor-tint: color-mix(in oklch, var(--acm-editor-accent) 11%, var(--acm-editor-card));
  --acm-editor-s-draft: color-mix(in oklch, var(--acm-editor-ink) 55%, var(--acm-editor-paper));
  --acm-editor-s-review: oklch(0.53 0.09 250);
  --acm-editor-s-changes: var(--acm-editor-warn);
  --acm-editor-s-approved: oklch(0.53 0.09 195);
  --acm-editor-s-scheduled: oklch(0.6 0.13 68);
  --acm-editor-s-published: var(--acm-editor-accent);
  --acm-editor-serif: ui-serif, "Iowan Old Style", Charter, Georgia, serif;
  --acm-editor-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-editor-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-editor-h, 680px);
  container-type: inline-size;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-editor-paper);
  color: var(--acm-editor-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--acm-editor-accent);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--acm-editor-rule);
}
:where(.acm-editor) *, :where(.acm-editor) *::before, :where(.acm-editor) *::after { box-sizing: border-box; }
:where(.acm-editor) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.acm-editor) button:disabled, :where(.acm-editor) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-editor) :is(h2, h3, p, ul, ol) { margin: 0; padding: 0; }
:where(.acm-editor) :is(ul, ol) { list-style: none; }
:where(.acm-editor) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-editor) :focus-visible { outline: 2px solid var(--acm-editor-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-editor) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--acm-editor-muted); background: var(--acm-editor-card); box-shadow: inset 0 0 0 1px var(--acm-editor-rule2), 0 1px 0 var(--acm-editor-rule2); }

.acm-editor__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head head" "list main side";
  grid-template-columns: clamp(252px, 26cqi, 310px) minmax(0, 1fr) clamp(268px, 26cqi, 316px);
  grid-template-rows: auto minmax(0, 1fr);
}

/* ---------- header ---------- */
.acm-editor__head {
  grid-area: head; display: flex; align-items: center; gap: 10px;
  padding: 10px 14px; border-bottom: 1px solid var(--acm-editor-rule);
  background: var(--acm-editor-card);
}
.acm-editor__brand { display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: var(--acm-editor-paper); background: var(--acm-editor-ink); stroke-width: 1.9; }
  & b { display: block; font: 700 14px/1.1 var(--acm-editor-serif); letter-spacing: -0.01em; }
  & span { font-size: 11px; color: var(--acm-editor-muted); letter-spacing: .02em; }
}
.acm-editor__save { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--acm-editor-muted); white-space: nowrap; font-variant-numeric: tabular-nums;
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--acm-editor-accent); transition: background .3s, scale .4s var(--acm-editor-spring); }
  &[data-dirty="true"] i { background: var(--acm-editor-s-scheduled); scale: 1.25; }
}
.acm-editor__hist { display: flex; gap: 2px;
  & button { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--acm-editor-muted); transition: background .15s, color .15s; }
  & button:not(:disabled):hover { background: var(--acm-editor-hover); color: var(--acm-editor-ink); }
  & button:disabled { opacity: .35; }
}
.acm-editor__me { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; font-size: 11px; font-weight: 700; letter-spacing: .03em; color: var(--acm-editor-paper); background: oklch(0.55 0.12 35); }
.acm-editor__tabs { display: none; }

/* ---------- entry list ---------- */
.acm-editor__list { grid-area: list; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr) auto; min-height: 0; border-right: 1px solid var(--acm-editor-rule); background: var(--acm-editor-sunk); }
.acm-editor__listtop { display: flex; gap: 6px; padding: 12px 12px 8px; }
.acm-editor__search { flex: 1; min-width: 0; display: flex; align-items: center; gap: 6px; height: 32px; padding: 0 6px 0 9px; border-radius: 8px; background: var(--acm-editor-card); box-shadow: inset 0 0 0 1px var(--acm-editor-rule2); color: var(--acm-editor-faint); transition: box-shadow .2s;
  & input { flex: 1; width: 0; min-width: 0; border: 0; outline: 0; background: none; font: inherit; color: var(--acm-editor-ink); }
  & input::placeholder { color: var(--acm-editor-faint); }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-editor-accent), 0 0 0 4px color-mix(in oklch, var(--acm-editor-accent) 14%, transparent); }
  &:has(input:focus) kbd { opacity: 0; }
}
.acm-editor__new { display: flex; align-items: center; gap: 4px; height: 32px; padding: 0 10px 0 8px; border-radius: 8px; font-weight: 600; color: var(--acm-editor-paper); background: var(--acm-editor-ink); transition: translate .2s var(--acm-editor-ease), background .2s;
  &:hover { background: color-mix(in oklch, var(--acm-editor-ink) 86%, var(--acm-editor-accent)); }
  &:active { translate: 0 1px; }
}
.acm-editor__filters { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 2px; margin: 0 12px 8px; padding: 2px; border-radius: 9px; background: color-mix(in oklch, var(--acm-editor-ink) 5%, transparent);
  & button { display: grid; justify-items: center; gap: 1px; padding: 5px 1px 4px; border-radius: 7px; font-size: 10px; font-weight: 600; letter-spacing: -0.01em; color: var(--acm-editor-muted); white-space: nowrap; transition: background .15s, color .15s, box-shadow .2s; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
  & button:hover { color: var(--acm-editor-ink); background: var(--acm-editor-hover); }
  & button[aria-selected="true"] { color: var(--acm-editor-ink); background: var(--acm-editor-card); box-shadow: 0 0 0 1px var(--acm-editor-rule), 0 1px 3px var(--acm-editor-rule2); }
  & b { order: -1; font-size: 15px; line-height: 1.1; font-weight: 650; color: inherit; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
}
.acm-editor__entries { overflow-y: auto; padding: 2px 8px 10px; scrollbar-width: thin; overscroll-behavior: contain; }
.acm-editor__entry {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 8px;
  padding: 10px 10px 10px 12px; margin-bottom: 2px; border-radius: 9px; cursor: pointer; outline-offset: -2px;
  transition: background .18s, box-shadow .18s;
  &:hover { background: var(--acm-editor-hover); }
  &[aria-selected="true"] { background: var(--acm-editor-card); box-shadow: 0 0 0 1px var(--acm-editor-rule2), 0 2px 8px -4px var(--acm-editor-rule2); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: 3px; top: 12px; bottom: 12px; width: 3px; border-radius: 3px; background: var(--acm-editor-ink); }
  & .acm-editor__et { grid-column: 1 / -1; font: 600 13.5px/1.3 var(--acm-editor-serif); text-wrap: pretty; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
  & .acm-editor__et.is-empty { color: var(--acm-editor-faint); font-style: italic; }
  & .acm-editor__em { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 11.5px; color: var(--acm-editor-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  @starting-style { opacity: 0; translate: 0 6px; }
}
.acm-editor__entry { transition: background .18s, box-shadow .18s, opacity .35s var(--acm-editor-ease), translate .35s var(--acm-editor-ease); }
.acm-editor__av { display: inline-grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; font-size: 8.5px; font-weight: 700; color: white; background: oklch(0.58 0.11 var(--h, 60)); flex: none; letter-spacing: .02em; }
.acm-editor__pill { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px 0 6px; border-radius: 99px; font-size: 11px; font-weight: 600; white-space: nowrap;
  --c: var(--acm-editor-s-draft);
  color: color-mix(in oklch, var(--c) 82%, var(--acm-editor-ink)); background: color-mix(in oklch, var(--c) 12%, var(--acm-editor-card));
  &::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
  &[data-s="review"] { --c: var(--acm-editor-s-review); }
  &[data-s="changes"] { --c: var(--acm-editor-s-changes); }
  &[data-s="approved"] { --c: var(--acm-editor-s-approved); }
  &[data-s="scheduled"] { --c: var(--acm-editor-s-scheduled); }
  &[data-s="published"] { --c: var(--acm-editor-s-published); }
}
.acm-editor__entry .acm-editor__pill { height: 18px; font-size: 10.5px; align-self: center; }
.acm-editor__empty { padding: 28px 16px; text-align: center; color: var(--acm-editor-muted); text-wrap: balance; }
.acm-editor__keys { display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 9px 14px; border-top: 1px solid var(--acm-editor-rule); font-size: 11px; color: var(--acm-editor-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}

/* ---------- editor ---------- */
.acm-editor__main { grid-area: main; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; background: var(--acm-editor-card); }
.acm-editor__bar { display: flex; align-items: center; gap: 8px; padding: 9px 14px; border-bottom: 1px solid var(--acm-editor-rule); min-width: 0;
  & .acm-editor__meta { min-width: 0; margin-right: auto; font-size: 12px; color: var(--acm-editor-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .acm-editor__meta b { color: var(--acm-editor-ink); font-weight: 600; }
}
.acm-editor__tool { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 550; color: var(--acm-editor-muted); box-shadow: inset 0 0 0 1px var(--acm-editor-rule2); white-space: nowrap; transition: background .15s, color .15s, box-shadow .15s;
  &:not(:disabled):hover { color: var(--acm-editor-ink); background: var(--acm-editor-hover); }
  &[aria-pressed="true"], &[aria-pressed="true"]:hover { color: var(--acm-editor-paper); background: var(--acm-editor-ink); box-shadow: none; }
  &:disabled { opacity: .45; }
  & b { font-variant-numeric: tabular-nums; }
  &.is-tk b { color: var(--acm-editor-warn); }
  &.is-primary { color: var(--acm-editor-paper); background: var(--acm-editor-accent); box-shadow: none; }
  &.is-primary:not(:disabled):hover { color: var(--acm-editor-paper); background: color-mix(in oklch, var(--acm-editor-accent) 85%, black); }
}
.acm-editor__back, .acm-editor__flowbtn { display: none; }
.acm-editor__canvas { position: relative; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scroll-timeline: --acm-editor-read y; }
.acm-editor__progress { position: sticky; top: 0; z-index: 2; height: 2px; margin-bottom: -2px; background: var(--acm-editor-accent); transform-origin: 0 50%; scale: 0 1; }
@supports (animation-timeline: scroll()) {
  .acm-editor__progress { animation: acm-editor-progress linear both; animation-timeline: --acm-editor-read; }
}
@keyframes acm-editor-progress { to { scale: 1 1; } }
.acm-editor__doc { max-width: 68ch; margin: 0 auto; padding: clamp(18px, 3.4cqi, 40px) clamp(16px, 4cqi, 48px) 56px;
  animation: acm-editor-in .42s var(--acm-editor-ease) both;
}
@keyframes acm-editor-in { from { opacity: 0; translate: 0 8px; } }
.acm-editor__kicker { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--acm-editor-muted); }
.acm-editor__field { display: block; width: 100%; border: 0; outline: 0; resize: none; background: none; color: inherit; padding: 0; field-sizing: content; border-radius: 4px;
  &::placeholder { color: var(--acm-editor-faint); }
  &:focus-visible { outline: none; box-shadow: -10px 0 0 -7px var(--acm-editor-accent); }
}
.acm-editor__title { font: 650 clamp(23px, 2.7cqi, 33px)/1.14 var(--acm-editor-serif); letter-spacing: -0.015em; text-wrap: balance; min-height: 1.2em; }
.acm-editor__dek { margin-top: 10px; font: italic 400 clamp(15px, 1.5cqi, 17.5px)/1.5 var(--acm-editor-serif); color: var(--acm-editor-muted); text-wrap: pretty; min-height: 1.5em; }
.acm-editor__byline { display: flex; align-items: center; gap: 8px; margin: 16px 0 18px; font-size: 12px; color: var(--acm-editor-muted);
  & b { color: var(--acm-editor-ink); font-weight: 600; }
}
.acm-editor__hero { position: relative; margin: 0 0 6px; border-radius: 10px; overflow: hidden; aspect-ratio: 16 / 8; background: var(--acm-editor-sunk);
  & > svg { width: 100%; height: 100%; display: block; stroke: none; }
  & .acm-editor__swap { position: absolute; right: 10px; bottom: 10px; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: white; background: oklch(0.2 0.02 60 / .55); backdrop-filter: blur(6px); transition: background .2s, translate .2s var(--acm-editor-ease); }
  & .acm-editor__swap:hover { background: oklch(0.2 0.02 60 / .75); translate: 0 -1px; }
}
.acm-editor__hero > svg { animation: acm-editor-hero .6s var(--acm-editor-ease) both; }
@keyframes acm-editor-hero { from { opacity: 0; scale: 1.04; filter: blur(6px); } }
.acm-editor__alt { display: flex; align-items: center; gap: 8px; margin-bottom: 22px; padding: 7px 10px; border-radius: 8px; font-size: 12px; background: var(--acm-editor-sunk); color: var(--acm-editor-muted);
  & span { font-weight: 650; font-size: 10.5px; letter-spacing: .07em; text-transform: uppercase; }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font: inherit; color: var(--acm-editor-ink); }
  & input::placeholder { color: var(--acm-editor-warn); opacity: .8; }
  &:has(input:placeholder-shown) { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--acm-editor-warn) 35%, transparent); }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-editor-accent); }
  & em { font-style: normal; font-variant-numeric: tabular-nums; color: var(--acm-editor-faint); }
}
.acm-editor__body { font: 400 16px/1.68 var(--acm-editor-serif); text-wrap: pretty; min-height: 8em; }
.acm-editor__read p { margin: 0 0 1em; font: 400 16px/1.68 var(--acm-editor-serif); text-wrap: pretty; }
.acm-editor__read p:first-child::first-letter { float: left; font-size: 3.1em; line-height: .9; padding: 4px 6px 0 0; font-weight: 650; }
.acm-editor__read mark { padding: 0 3px; border-radius: 3px; color: var(--acm-editor-warn); background: color-mix(in oklch, var(--acm-editor-warn) 14%, transparent); font: 700 12px/1 ui-monospace, Menlo, monospace; }
.acm-editor__tags { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 26px; padding-top: 16px; border-top: 1px solid var(--acm-editor-rule); }
.acm-editor__tag { display: inline-flex; align-items: center; gap: 2px; height: 26px; padding: 0 4px 0 10px; border-radius: 99px; font-size: 12px; font-weight: 550; background: var(--acm-editor-tint); color: color-mix(in oklch, var(--acm-editor-accent) 70%, var(--acm-editor-ink));
  & button { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; transition: background .15s; }
  & button:hover { background: color-mix(in oklch, var(--acm-editor-accent) 20%, transparent); }
  & svg { width: 12px; height: 12px; }
  @starting-style { opacity: 0; scale: .7; }
  transition: opacity .3s, scale .4s var(--acm-editor-spring);
}
.acm-editor__tagin { width: 9em; height: 26px; padding: 0 10px; border: 0; border-radius: 99px; outline: 0; font: inherit; font-size: 12px; color: var(--acm-editor-ink); background: none; box-shadow: inset 0 0 0 1px var(--acm-editor-rule2);
  &:focus { box-shadow: inset 0 0 0 1.5px var(--acm-editor-accent); }
}
.acm-editor__sugg { font-size: 12px; height: 26px; padding: 0 9px; border-radius: 99px; color: var(--acm-editor-muted); border: 1px dashed var(--acm-editor-rule2); transition: color .15s, border-color .15s, background .15s;
  &:hover { color: var(--acm-editor-ink); border-color: var(--acm-editor-faint); background: var(--acm-editor-hover); }
}

/* ---------- workflow ---------- */
.acm-editor__side { grid-area: side; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); min-height: 0; border-left: 1px solid var(--acm-editor-rule); background: var(--acm-editor-paper); }
.acm-editor__sidehead { display: flex; align-items: center; gap: 8px; padding: 13px 16px 11px;
  & h2 { margin-right: auto; font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--acm-editor-muted); }
}
.acm-editor__sideclose { display: none; place-items: center; width: 28px; height: 28px; border-radius: 7px; color: var(--acm-editor-muted);
  &:hover { background: var(--acm-editor-hover); color: var(--acm-editor-ink); }
}
.acm-editor__sidebody { overflow-y: auto; overscroll-behavior: contain; padding: 4px 16px 20px; scrollbar-width: thin; }
.acm-editor__track {
  --acm-editor-p: 0;
  position: relative; display: grid; grid-template-columns: repeat(5, 1fr); margin: 6px -10px 14px;
  transition: --acm-editor-p .9s var(--acm-editor-spring);
  &::before { content: ""; position: absolute; left: 10%; right: 10%; top: 8px; height: 2px; border-radius: 2px;
    background: linear-gradient(90deg, var(--acm-editor-ink) calc(var(--acm-editor-p) * 100%), var(--acm-editor-rule2) 0); }
  & li { position: relative; display: grid; justify-items: center; gap: 6px; font-size: 10px; letter-spacing: -0.005em; white-space: nowrap; font-weight: 600; color: var(--acm-editor-faint); text-align: center; transition: color .3s; }
  & i { width: 18px; height: 18px; border-radius: 50%; background: var(--acm-editor-paper); box-shadow: inset 0 0 0 2px var(--acm-editor-rule2);
    transition: background .3s calc(var(--i) * 60ms), box-shadow .3s calc(var(--i) * 60ms), scale .5s var(--acm-editor-spring) calc(var(--i) * 60ms); }
  & li.is-done { color: var(--acm-editor-muted); }
  & li.is-done i { background: var(--acm-editor-ink); box-shadow: inset 0 0 0 5px var(--acm-editor-ink), inset 0 0 0 9px var(--acm-editor-paper); }
  & li.is-now { color: var(--acm-editor-ink); }
  & li.is-now i { scale: 1.12; background: var(--acm-editor-paper); box-shadow: inset 0 0 0 2px var(--c, var(--acm-editor-ink)), inset 0 0 0 5px var(--acm-editor-paper), inset 0 0 0 9px var(--c, var(--acm-editor-ink)); animation: acm-editor-pulse 2.4s var(--acm-editor-ease) infinite; }
  & li.is-skip span { text-decoration: line-through; text-decoration-thickness: 1px; }
}
@keyframes acm-editor-pulse { 0%, 100% { filter: drop-shadow(0 0 0 transparent); } 50% { filter: drop-shadow(0 0 5px color-mix(in oklch, var(--c, var(--acm-editor-ink)) 55%, transparent)); } }
.acm-editor__track[data-s="changes"] { --c: var(--acm-editor-s-changes); }
.acm-editor__track[data-s="review"] { --c: var(--acm-editor-s-review); }
.acm-editor__track[data-s="approved"] { --c: var(--acm-editor-s-approved); }
.acm-editor__track[data-s="scheduled"] { --c: var(--acm-editor-s-scheduled); }
.acm-editor__track[data-s="published"] { --c: var(--acm-editor-s-published); }
.acm-editor__status { font-size: 12.5px; line-height: 1.5; color: var(--acm-editor-muted); text-wrap: pretty;
  & b { color: var(--acm-editor-ink); font-weight: 600; }
}
.acm-editor__note { margin-top: 10px; padding: 10px 12px; border-radius: 8px; font: italic 13px/1.5 var(--acm-editor-serif); color: var(--acm-editor-ink); background: color-mix(in oklch, var(--acm-editor-warn) 8%, var(--acm-editor-card)); box-shadow: inset 3px 0 0 var(--acm-editor-warn); text-wrap: pretty;
  & small { display: block; margin-top: 4px; font: 600 11px/1.3 system-ui, sans-serif; font-style: normal; color: var(--acm-editor-muted); }
}
.acm-editor__actions { display: grid; gap: 6px; margin: 14px 0 6px;
  & > * { animation: acm-editor-rise .4s var(--acm-editor-ease) both; animation-delay: calc(var(--i, 0) * 45ms); }
}
@keyframes acm-editor-rise { from { opacity: 0; translate: 0 5px; } }
.acm-editor__btn { display: flex; align-items: center; justify-content: center; gap: 8px; height: 36px; padding: 0 12px; border-radius: 9px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--acm-editor-rule2); background: var(--acm-editor-card); transition: background .15s, box-shadow .15s, translate .15s var(--acm-editor-ease), opacity .2s;
  &:not(:disabled):hover { background: var(--acm-editor-hover); box-shadow: inset 0 0 0 1px var(--acm-editor-faint); }
  &:not(:disabled):active { translate: 0 1px; }
  &.is-primary { color: var(--acm-editor-paper); background: var(--acm-editor-ink); box-shadow: none; }
  &.is-primary:not(:disabled):hover { background: color-mix(in oklch, var(--acm-editor-ink) 85%, var(--acm-editor-accent)); box-shadow: none; }
  &.is-danger { color: var(--acm-editor-warn); }
  &:disabled { opacity: .42; }
  & kbd { margin-left: auto; background: color-mix(in oklch, var(--acm-editor-paper) 14%, transparent); color: inherit; box-shadow: none; opacity: .8; }
  &:not(.is-primary) kbd { background: var(--acm-editor-sunk); }
  & span { margin-right: auto; }
  & kbd + kbd { margin-left: 0; }
}
.acm-editor__why { font-size: 11.5px; color: var(--acm-editor-warn); text-wrap: pretty; }
.acm-editor__compose { display: grid; gap: 6px;
  & textarea { width: 100%; min-height: 68px; padding: 8px 10px; border: 0; border-radius: 8px; outline: 0; resize: vertical; font: inherit; color: inherit; background: var(--acm-editor-card); box-shadow: inset 0 0 0 1px var(--acm-editor-rule2); }
  & textarea:focus { box-shadow: inset 0 0 0 1.5px var(--acm-editor-accent); }
  & div { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; }
}
.acm-editor__picker { display: grid; gap: 8px; padding: 10px; border-radius: 10px; background: var(--acm-editor-card); box-shadow: inset 0 0 0 1px var(--acm-editor-rule2);
  & h4 { margin: 0; font-size: 11px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--acm-editor-muted); }
}
.acm-editor__days { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px;
  & button { position: relative; display: grid; justify-items: center; gap: 1px; padding: 6px 0 8px; border-radius: 7px; font-size: 10px; color: var(--acm-editor-muted); transition: background .15s, color .15s; }
  & button b { font-size: 14px; font-weight: 650; color: var(--acm-editor-ink); font-variant-numeric: tabular-nums; }
  & button:hover { background: var(--acm-editor-hover); }
  & button[aria-checked="true"] { background: var(--acm-editor-ink); color: color-mix(in oklch, var(--acm-editor-paper) 70%, transparent); }
  & button[aria-checked="true"] b { color: var(--acm-editor-paper); }
  & button[data-busy]::after { content: ""; position: absolute; bottom: 3px; width: 4px; height: 4px; border-radius: 50%; background: var(--acm-editor-s-scheduled); }
}
.acm-editor__slots { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px;
  & button { height: 30px; border-radius: 7px; font: 600 12px/1 ui-monospace, Menlo, monospace; box-shadow: inset 0 0 0 1px var(--acm-editor-rule2); transition: background .15s, box-shadow .15s; }
  & button:not(:disabled):hover { background: var(--acm-editor-hover); }
  & button[aria-checked="true"] { color: var(--acm-editor-paper); background: var(--acm-editor-s-scheduled); box-shadow: none; }
  & button:disabled { color: var(--acm-editor-faint); text-decoration: line-through; box-shadow: inset 0 0 0 1px var(--acm-editor-rule); }
}
.acm-editor__block { margin-top: 20px; padding-top: 14px; border-top: 1px solid var(--acm-editor-rule);
  & h3 { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 10px; font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--acm-editor-muted); }
}
.acm-editor__score { font: 650 12px/1 system-ui, sans-serif; letter-spacing: 0; text-transform: none; color: var(--acm-editor-ink); font-variant-numeric: tabular-nums; }
.acm-editor__meter { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px; margin-bottom: 10px;
  & i { height: 4px; border-radius: 2px; background: var(--acm-editor-rule2); transform-origin: 0 50%; transition: background .35s calc(var(--i) * 45ms); }
  & i.is-on { background: var(--acm-editor-accent); animation: acm-editor-seg .5s var(--acm-editor-spring) calc(var(--i) * 45ms) both; }
}
@keyframes acm-editor-seg { from { scale: .2 1; } }
.acm-editor__ready:has(.acm-editor__meter i:nth-child(7).is-on) .acm-editor__score { color: var(--acm-editor-accent); }
.acm-editor__checks { display: grid; gap: 1px;
  & li > * { display: flex; align-items: center; gap: 9px; width: 100%; padding: 6px 8px; margin: 0 -8px; width: calc(100% + 16px); border-radius: 7px; font-size: 12.5px; text-align: left; color: var(--acm-editor-ink); }
  & button:hover { background: var(--acm-editor-hover); }
  & em { margin-left: auto; font-style: normal; font-size: 11.5px; color: var(--acm-editor-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & svg { width: 15px; height: 15px; }
  & .is-ok svg { color: var(--acm-editor-accent); }
  & .is-bad svg { color: var(--acm-editor-warn); }
  & .is-bad { color: var(--acm-editor-ink); }
  & .is-ok span { color: var(--acm-editor-muted); }
}
.acm-editor__reviewers { display: grid; gap: 2px;
  & button { display: flex; align-items: center; gap: 9px; padding: 6px 8px; margin: 0 -8px; border-radius: 8px; text-align: left; transition: background .15s; }
  & button:hover { background: var(--acm-editor-hover); }
  & button span { display: grid; line-height: 1.25; }
  & button small { font-size: 11px; color: var(--acm-editor-muted); }
  & .acm-editor__av { width: 26px; height: 26px; font-size: 10px; }
  & button::after { content: ""; margin-left: auto; width: 16px; height: 16px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--acm-editor-rule2); transition: box-shadow .25s var(--acm-editor-ease); }
  & button[aria-checked="true"]::after { box-shadow: inset 0 0 0 5px var(--acm-editor-ink); }
}
.acm-editor__history { display: grid; position: relative;
  & li { position: relative; display: grid; grid-template-columns: 14px minmax(0, 1fr) auto; align-items: start; gap: 2px 9px; padding: 0 0 12px; font-size: 12px; }
  & li::before { content: ""; position: absolute; left: 6px; top: 12px; bottom: 0; width: 1px; background: var(--acm-editor-rule2); }
  & li:last-child::before { display: none; }
  & i { width: 9px; height: 9px; margin: 4px 0 0 2px; border-radius: 50%; background: var(--acm-editor-paper); box-shadow: inset 0 0 0 2px var(--acm-editor-faint); }
  & li.is-flow i { box-shadow: inset 0 0 0 5px var(--c, var(--acm-editor-ink)); }
  & b { font-weight: 600; }
  & small { display: block; color: var(--acm-editor-muted); font-size: 11px; font-variant-numeric: tabular-nums; }
  & button { font-size: 11.5px; font-weight: 600; color: var(--acm-editor-accent); padding: 2px 6px; border-radius: 5px; }
  & button:hover { background: var(--acm-editor-tint); }
  & .acm-editor__cur { font-size: 10.5px; font-weight: 650; color: var(--acm-editor-faint); letter-spacing: .04em; text-transform: uppercase; padding-top: 2px; }
}

/* ---------- toast ---------- */
.acm-editor__toast { position: absolute; left: 50%; bottom: 16px; z-index: 30; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 9px 9px 9px 14px; border-radius: 10px; color: var(--acm-editor-paper); background: var(--acm-editor-ink); box-shadow: 0 10px 30px -10px oklch(0.2 0.02 60 / .5); font-size: 12.5px;
  translate: -50% 0; transition: opacity .25s, translate .45s var(--acm-editor-spring), visibility 0s .45s; 
  &:not(.is-on) { opacity: 0; translate: -50% 14px; visibility: hidden; }
  &.is-on { transition: opacity .25s, translate .45s var(--acm-editor-spring), visibility 0s; }
  & button { padding: 4px 9px; border-radius: 6px; font-weight: 650; color: color-mix(in oklch, var(--acm-editor-accent) 50%, white); }
  & button:hover { background: color-mix(in oklch, white 12%, transparent); }
}

/* ---------- responsive ---------- */
@container (max-width: 959px) {
  .acm-editor__app { grid-template-areas: "head head" "list main"; grid-template-columns: clamp(220px, 32cqi, 280px) minmax(0, 1fr); }
  .acm-editor__side { position: absolute; z-index: 20; top: 0; right: 0; bottom: 0; width: min(340px, 100%); box-shadow: -24px 0 48px -24px oklch(0.2 0.02 60 / .35);
    translate: 100% 0; visibility: hidden; transition: translate .45s var(--acm-editor-ease), visibility 0s .45s; }
  .acm-editor[data-view="flow"] .acm-editor__side { translate: 0 0; visibility: visible; transition: translate .45s var(--acm-editor-ease), visibility 0s; }
  .acm-editor__sideclose { display: grid; }
  .acm-editor__flowbtn { display: inline-flex; }
}
@container (max-width: 759px) {
  .acm-editor__app { grid-template-areas: "head" "pane"; grid-template-columns: minmax(0, 1fr); }
  .acm-editor__list, .acm-editor__main { grid-area: pane; border: 0; }
  .acm-editor[data-view="list"] .acm-editor__main, .acm-editor:not([data-view="list"]) .acm-editor__list { display: none; }
  .acm-editor__side { grid-area: pane; position: static; width: auto; box-shadow: none; border: 0; translate: none; visibility: visible; transition: none; display: none; }
  .acm-editor[data-view="flow"] .acm-editor__side { display: grid; }
  .acm-editor[data-view="flow"] .acm-editor__main { display: none; }
  .acm-editor__brand div, .acm-editor__me, .acm-editor__save span { display: none; }
  .acm-editor__tabs { display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--acm-editor-sunk); box-shadow: inset 0 0 0 1px var(--acm-editor-rule);
    & button { padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acm-editor-muted); }
    & button[aria-selected="true"] { color: var(--acm-editor-ink); background: var(--acm-editor-card); box-shadow: 0 1px 2px var(--acm-editor-rule2); }
  }
  .acm-editor__brand { margin-right: 0; }
  .acm-editor__save { margin-left: auto; }
  .acm-editor__back { display: inline-flex; }
  .acm-editor__flowbtn { display: none; }
  .acm-editor__bar .acm-editor__meta { display: none; }
  .acm-editor__bar { flex-wrap: wrap; }
  .acm-editor__tool .acm-editor__lbl { display: none; }
}
@container (max-width: 420px) {
  .acm-editor__head { padding: 8px 10px; gap: 6px; }
  .acm-editor__tabs button { padding: 5px 8px; }
  .acm-editor__hist button { width: 26px; }
}

@media (prefers-reduced-motion: reduce) {
  .acm-editor *, .acm-editor *::before, .acm-editor *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
  .acm-editor .acm-editor__progress { animation: none; scale: 0 1; }
  .acm-editor .acm-editor__track li.is-now i { animation: none; }
}

js:
// Editorial desk. ENTRIES is the only mutable data. Filter counts, the publish checklist,
// the workflow track, the actions on offer and the history are all derived from it.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1)';
const MAC = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
const MOD = MAC ? '⌘' : 'Ctrl';
$$('.acm-editor__mod').forEach((k) => (k.textContent = MOD));

const ICON = {
  ok: '<circle cx="12" cy="12" r="8.5"/><path d="m8.3 12.3 2.5 2.5 5-5.2"/>',
  bad: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.8v5M12 15.9v.2"/>',
  x: '<path d="M7 7l10 10M17 7 7 17"/>',
  back: '<path d="M15 5 8 12l7 7"/>',
  eye: '<path d="M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z"/><circle cx="12" cy="12" r="2.8"/>',
  flow: '<circle cx="6" cy="6" r="2.2"/><circle cx="18" cy="18" r="2.2"/><path d="M6 8.2v3.3a3 3 0 0 0 3 3h6a3 3 0 0 1 3 3v-1.3"/>',
  find: '<path d="M4 6h10M4 12h7M4 18h6"/><circle cx="17" cy="14" r="3.5"/><path d="m19.6 16.6 2 2"/>',
  swap: '<path d="M4 9h13l-3.5-3.5M20 15H7l3.5 3.5"/>',
  send: '<path d="M4 12 20 4l-5 16-3.5-6.5z"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
  live: '<circle cx="12" cy="12" r="2.6"/><path d="M7.8 7.8a6 6 0 0 0 0 8.4M16.2 7.8a6 6 0 0 1 0 8.4M5 5a10 10 0 0 0 0 14M19 5a10 10 0 0 1 0 14"/>',
  undo: '<path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>',
  trash: '<path d="M4.5 7h15M10 4h4M6.5 7l.8 12.2a1.5 1.5 0 0 0 1.5 1.3h6.4a1.5 1.5 0 0 0 1.5-1.3L17.5 7"/>',
  save: '<path d="M5 4h11l3 3v13H5z"/><path d="M8 4v5h7V4M8 20v-6h8v6"/>',
};
const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;

const PEOPLE = {
  ic: { name: 'Ines Calloway', short: 'Ines', role: 'Staff writer', h: 35 },
  tw: { name: 'Tomasz Wren', short: 'Tomasz', role: 'Data reporter', h: 250 },
  ao: { name: 'Ada Okafor', short: 'Ada', role: 'Features editor', h: 155 },
  bs: { name: 'Ben Sato', short: 'Ben', role: 'Copy chief', h: 300 },
  cm: { name: 'Clio Marsh', short: 'Clio', role: 'Managing editor', h: 80 },
};
const ME = 'ic';
const REVIEWERS = ['ao', 'bs', 'cm'];
const initials = (k) => PEOPLE[k].name.split(' ').map((w) => w[0]).join('');
const av = (k) => `<span class="acm-editor__av" style="--h:${PEOPLE[k].h}" aria-hidden="true">${initials(k)}</span>`;
const DAYS = [['Sat', 3], ['Sun', 4], ['Mon', 5], ['Tue', 6], ['Wed', 7], ['Thu', 8], ['Fri', 9]];
const SLOTS = ['07:00', '09:00', '12:30', '17:00'];
const when = (s) => `${DAYS[s.d][0]} ${DAYS[s.d][1]} Oct, ${s.t}`;
const STATE = {
  draft: { label: 'Draft', step: 0, group: 'drafts' },
  changes: { label: 'Changes requested', step: 1, group: 'drafts' },
  review: { label: 'In review', step: 1, group: 'review' },
  approved: { label: 'Approved', step: 2, group: 'review' },
  scheduled: { label: 'Scheduled', step: 3, group: 'scheduled' },
  published: { label: 'Published', step: 4, group: 'published' },
};
const GROUPS = [['all', 'All'], ['drafts', 'Drafts'], ['review', 'Review'], ['scheduled', 'Scheduled'], ['published', 'Live']];
const SUGGEST = ['harbour', 'islands', 'transport', 'council', 'food', 'history', 'climate', 'walks', 'data', 'letters'];
const HEROES = [
  { kind: 'sea', a: 215, b: 30 }, { kind: 'hills', a: 150, b: 85 }, { kind: 'dots', a: 270, b: 60 },
  { kind: 'sea', a: 195, b: 55 }, { kind: 'hills', a: 35, b: 140 }, { kind: 'dots', a: 20, b: 85 },
];
const T0 = Date.now(), MIN = 60000;

const E = (o) => Object.assign({ tags: [], alt: '', reviewer: null, note: '', sched: null, viaSched: false, liveEdits: false, hero: 0, hist: [] }, o);
let ENTRIES = [
  E({ id: 'e1', state: 'draft', author: 'ic', edited: T0 - 14 * MIN, hero: 0, tags: ['islands', 'transport'],
    title: 'The last ferry operator on Pell Island',
    dek: 'Marguerite Doyle has run the 6:15 crossing for thirty-one years. In March the council stops paying for it.',
    body: "Marguerite Doyle starts the engine of the Kittiwake at 5:40, twenty-five minutes before anyone is waiting on the slipway. She likes the boat warm when the first passengers step on: two nurses for the mainland clinic, a postman, and on Thursdays a man who sells eggs at the Quayside market.\n\nThe crossing takes eleven minutes in calm water and up to twenty in a north-easterly. Doyle has made it, by her own count, a little over [TK] times. The ferry carries 140 people on a busy summer day and 18 on a quiet one in February.\n\nFrom March the council's transport budget will no longer cover the subsidy, which last year came to £212,000. A community trust has offered to take the route on, but its business plan assumes a fare rise of [TK] per cent, and nobody on the island has seen it yet.",
    hist: [{ r: 12, by: 'ic', at: T0 - 2 * 1440 * MIN, label: 'Created draft', snap: { title: 'The last ferryman of Pell Island', dek: 'For thirty-one years one woman has run the 6:15 crossing.' } },
      { r: 13, by: 'ic', at: T0 - 190 * MIN, label: 'Autosave', snap: { title: 'The last ferry operator on Pell Island', dek: 'For thirty-one years one woman has run the 6:15 crossing. In March the subsidy ends.' } },
      { r: 14, by: 'ic', at: T0 - 14 * MIN, label: 'Autosave' }] }),
  E({ id: 'e2', state: 'review', author: 'tw', reviewer: 'ao', edited: T0 - 128 * MIN, hero: 3, tags: ['climate', 'data', 'history'],
    alt: 'Survey sheet from 1998 with the flood line drawn in red ink',
    title: 'What the 1998 flood maps got wrong',
    dek: 'Of the 611 homes that claimed after the 2019 flood, 248 were outside the zone the maps said was at risk.',
    body: 'In 1998 the river authority drew a line around 2,300 homes in the lower town and called it the one-in-a-hundred-year flood zone. Since then the water has crossed that line four times.\n\nWe compared the original survey sheets, digitised by the county archive last spring, with the insurance claims filed after each flood. Of the 611 properties that claimed in 2019, 248 sat outside the zone.\n\nThe survey was not careless. It used the best gauges available, on a river that had been straightened in the 1960s and has spent the decades since trying to bend back.',
    hist: [{ r: 3, by: 'tw', at: T0 - 1440 * MIN, label: 'Created draft' }, { r: 7, by: 'tw', at: T0 - 128 * MIN, label: 'Submitted to Ada Okafor', flow: 'review' }] }),
  E({ id: 'e3', state: 'scheduled', author: 'ic', reviewer: 'cm', viaSched: true, sched: { d: 6, t: '07:00' }, edited: T0 - 1310 * MIN, hero: 2, tags: ['food', 'walks'],
    alt: 'Strings of bulbs over the market stalls on Saltmarsh Row at dusk',
    title: 'A field guide to the night markets of Saltmarsh Row',
    dek: 'Forty-two stalls, one street, every Friday from dusk. Where to start, what sells out, and the custard tart worth queueing for.',
    body: "The stalls go up at dusk on Fridays, when the fish market has been hosed down and the strip lights are switched off. By eight there are forty-two of them, run by families who mostly have day jobs somewhere else.\n\nStart at the north end with the Hossain family's crab pakoras, which sell out by nine. Halfway down, the Ferreira sisters grill sardines over a half oil drum. If you only have room for one dessert, queue for the warm custard tarts at the stall with no sign.",
    hist: [{ r: 5, by: 'ic', at: T0 - 3 * 1440 * MIN, label: 'Created draft' }, { r: 9, by: 'cm', at: T0 - 1400 * MIN, label: 'Approved by Clio Marsh', flow: 'approved' }, { r: 10, by: 'cm', at: T0 - 1310 * MIN, label: 'Scheduled for Fri 9 Oct, 07:00', flow: 'scheduled' }] }),
  E({ id: 'e4', state: 'published', author: 'tw', reviewer: 'ao', edited: T0 - 2 * 1440 * MIN - 300 * MIN, hero: 4, tags: ['council', 'transport'],
    alt: 'Quarry Lane at the station roundabout, looking towards the school',
    title: 'Council approves the Quarry Lane cycleway, 6–3',
    dek: 'The £1.4m scheme removes 38 parking spaces and adds two signal crossings. Work starts in January.',
    body: "After four hours of debate on Tuesday night, councillors voted six to three to build a protected cycleway along the length of Quarry Lane, from the station roundabout to the school gates.\n\nThe £1.4m scheme will remove 38 parking spaces and add two signal-controlled crossings. Construction is due to start in January and last eleven weeks.\n\nResidents' groups were split. A petition against the loss of parking gathered 412 signatures; a counter-petition from parents at Quarry Lane Primary gathered 655.",
    hist: [{ r: 4, by: 'ao', at: T0 - 2 * 1440 * MIN - 340 * MIN, label: 'Approved by Ada Okafor', flow: 'approved' }, { r: 5, by: 'ao', at: T0 - 2 * 1440 * MIN - 300 * MIN, label: 'Published Wed 30 Sep', flow: 'published' }] }),
  E({ id: 'e5', state: 'published', author: 'ic', reviewer: 'ao', viaSched: true, edited: T0 - 8 * 1440 * MIN, hero: 1, tags: ['climate', 'harbour'],
    alt: 'Volunteers scrubbing oyster tanks in the hatchery shed',
    title: 'Inside the oyster hatchery that saved the bay',
    dek: 'Ten years after the native beds were declared extinct, divers counted living reefs at six of nine historic sites.',
    body: 'Behind the old lifeboat station, in a shed that still smells of diesel, eight tanks hold roughly four million oyster larvae, each smaller than a grain of sand.\n\nTen years ago the bay\'s native oyster beds were declared functionally extinct. Since then the hatchery has returned 26 million juveniles to the water, and divers counted living reefs at six of the nine historic sites this summer.\n\nThe work is slow and wet and mostly done by volunteers, who arrive at seven to scrub the tanks before the tide turns.',
    hist: [{ r: 8, by: 'ao', at: T0 - 9 * 1440 * MIN, label: 'Scheduled for Thu 24 Sep, 07:00', flow: 'scheduled' }, { r: 9, by: 'ao', at: T0 - 8 * 1440 * MIN, label: 'Published Thu 24 Sep', flow: 'published' }] }),
  E({ id: 'e6', state: 'changes', author: 'ic', reviewer: 'bs', edited: T0 - 26 * 60 * MIN, hero: 5, tags: ['food', 'history'],
    alt: "Loaves cooling on a rack at Harrow's bakery on Fore Street",
    note: "Fact-check the 1911 date and get a second source for where the starter came from. Otherwise lovely.",
    title: 'Ten bakeries, one sourdough starter',
    dek: "A crock of starter fed every day since 1911 has quietly spread to nine other bakeries across the county.",
    body: "The starter lives in a stoneware crock at Harrow's on Fore Street and, according to the family, has been fed every day since 1911.\n\nOver the past decade, jars of it have travelled to nine other bakeries across the county. We visited all ten in a week and ate, conservatively, [TK] loaves.",
    hist: [{ r: 2, by: 'ic', at: T0 - 30 * 60 * MIN, label: 'Submitted to Ben Sato', flow: 'review' }, { r: 3, by: 'bs', at: T0 - 26 * 60 * MIN, label: 'Ben Sato requested changes', flow: 'changes' }] }),
  E({ id: 'e7', state: 'draft', author: 'cm', edited: T0 - 50 * MIN, hero: 3, tags: ['letters'],
