/* Media library. Re-theme with --acm-media-bg, -ink, -accent and -bad. Neutral greys keep
   photographs honest; the single amber accent marks selection and the focal point. */
.acm-media {
  --acm-media-bg: oklch(0.185 0.004 75);
  --acm-media-ink: oklch(0.94 0.006 85);
  --acm-media-accent: oklch(0.81 0.14 76);
  --acm-media-bad: oklch(0.69 0.17 28);

  --acm-media-panel: color-mix(in oklch, var(--acm-media-ink) 3.5%, var(--acm-media-bg));
  --acm-media-raise: color-mix(in oklch, var(--acm-media-ink) 8%, var(--acm-media-bg));
  --acm-media-muted: color-mix(in oklch, var(--acm-media-ink) 60%, var(--acm-media-bg));
  --acm-media-faint: color-mix(in oklch, var(--acm-media-ink) 38%, var(--acm-media-bg));
  --acm-media-rule: color-mix(in oklch, var(--acm-media-ink) 8%, transparent);
  --acm-media-rule2: color-mix(in oklch, var(--acm-media-ink) 15%, transparent);
  --acm-media-hover: color-mix(in oklch, var(--acm-media-ink) 6%, transparent);
  --acm-media-glow: color-mix(in oklch, var(--acm-media-accent) 22%, transparent);
  --acm-media-on: oklch(0.2 0.03 75);
  --acm-media-c-img: var(--acm-media-accent);
  --acm-media-c-vid: oklch(0.72 0.09 200);
  --acm-media-c-doc: color-mix(in oklch, var(--acm-media-ink) 45%, var(--acm-media-bg));
  --acm-media-mono: ui-monospace, Menlo, monospace;
  --acm-media-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-media-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-media-h, 680px);
  container-type: inline-size;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-media-bg);
  color: var(--acm-media-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--acm-media-accent);
  outline: none;
}
:where(.acm-media) *, :where(.acm-media) *::before, :where(.acm-media) *::after { box-sizing: border-box; }
:where(.acm-media) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.acm-media) button:disabled, :where(.acm-media) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-media) :is(h2, h3, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
:where(.acm-media) :is(ul, ol) { list-style: none; }
:where(.acm-media) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-media) :focus-visible { outline: 2px solid var(--acm-media-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-media) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acm-media-mono); color: var(--acm-media-muted); background: var(--acm-media-raise); box-shadow: inset 0 0 0 1px var(--acm-media-rule2); }

.acm-media__app {
  height: 100%;
  display: grid;
  grid-template-areas: "side bar detail" "side main detail";
  grid-template-columns: 210px minmax(0, 1fr) clamp(300px, 29cqi, 340px);
  grid-template-rows: auto minmax(0, 1fr);
}

/* ---------- folders ---------- */
.acm-media__side { grid-area: side; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; padding: 14px 10px 12px; border-right: 1px solid var(--acm-media-rule); background: var(--acm-media-panel); }
.acm-media__brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 16px;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: var(--acm-media-on); background: var(--acm-media-accent); stroke-width: 1.9; }
  & b { display: block; font-size: 13.5px; font-weight: 700; letter-spacing: -0.01em; }
  & span { font-size: 11px; color: var(--acm-media-muted); }
}
.acm-media__folders { display: grid; align-content: start; gap: 1px; overflow-y: auto;
  & button { display: flex; align-items: center; gap: 9px; width: 100%; padding: 7px 9px; border-radius: 8px; text-align: left; color: var(--acm-media-muted); font-weight: 500; transition: background .15s, color .15s; }
  & button:hover { background: var(--acm-media-hover); color: var(--acm-media-ink); }
  & button[aria-selected="true"] { background: var(--acm-media-raise); color: var(--acm-media-ink); }
  & button[aria-selected="true"] svg { color: var(--acm-media-accent); }
  & button.is-target { background: var(--acm-media-glow); color: var(--acm-media-ink); box-shadow: inset 0 0 0 1px var(--acm-media-accent); }
  & b { margin-left: auto; font-size: 11px; font-weight: 500; color: var(--acm-media-faint); font-variant-numeric: tabular-nums; }
  & .acm-media__sep { height: 1px; margin: 8px 9px; background: var(--acm-media-rule); }
}
.acm-media__storage { padding: 12px 8px 2px; border-top: 1px solid var(--acm-media-rule); font-size: 11.5px; color: var(--acm-media-muted);
  & p { display: flex; justify-content: space-between; margin-bottom: 8px; font-variant-numeric: tabular-nums; }
  & p b { color: var(--acm-media-ink); font-weight: 600; }
  & .acm-media__meter { display: flex; height: 6px; border-radius: 3px; overflow: hidden; background: var(--acm-media-raise); }
  & .acm-media__meter i { height: 100%; transition: flex-basis .6s var(--acm-media-ease); }
  & ul { display: grid; gap: 3px; margin-top: 9px; }
  & li { display: flex; align-items: center; gap: 7px; font-variant-numeric: tabular-nums; }
  & li i { width: 7px; height: 7px; border-radius: 2px; }
  & li span { margin-left: auto; color: var(--acm-media-faint); }
}

/* ---------- toolbar ---------- */
.acm-media__bar { grid-area: bar; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px 14px 10px; min-width: 0;
  & .acm-media__search { flex: 1 1 calc(100% - 120px); }
  & .acm-media__upload { order: 1; }
  & .acm-media__types { order: 2; margin-right: auto; }
  & .acm-media__menuwrap { order: 3; }
  & .acm-media__views { order: 4; }
}
.acm-media__search { flex: 1; min-width: 0; display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 6px 0 10px; border-radius: 8px; background: var(--acm-media-panel); box-shadow: inset 0 0 0 1px var(--acm-media-rule2); color: var(--acm-media-faint); transition: box-shadow .2s;
  & input { flex: 1; width: 0; min-width: 0; border: 0; outline: 0; background: none; font: inherit; color: var(--acm-media-ink); }
  & input::placeholder { color: var(--acm-media-faint); }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-media-accent); }
  &:has(input:focus) kbd { opacity: 0; }
}
.acm-media__types, .acm-media__views { display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--acm-media-panel); box-shadow: inset 0 0 0 1px var(--acm-media-rule);
  & button { display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 550; color: var(--acm-media-muted); white-space: nowrap; transition: background .15s, color .15s; }
  & button:hover { color: var(--acm-media-ink); }
  & button[aria-checked="true"] { color: var(--acm-media-ink); background: var(--acm-media-raise); box-shadow: 0 1px 2px oklch(0 0 0 / .35); }
  & b { font-size: 10.5px; font-weight: 500; color: var(--acm-media-faint); font-variant-numeric: tabular-nums; }
}
.acm-media__views button { padding: 0 6px; }
.acm-media__ctl { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 550; color: var(--acm-media-muted); box-shadow: inset 0 0 0 1px var(--acm-media-rule2); white-space: nowrap; transition: background .15s, color .15s;
  &:not(:disabled):hover, &[aria-expanded="true"] { color: var(--acm-media-ink); background: var(--acm-media-hover); }
  & b { color: var(--acm-media-ink); font-weight: 600; }
  &:disabled { opacity: .4; }
}
.acm-media__menuwrap { position: relative; }
.acm-media__menu { position: absolute; z-index: 40; top: calc(100% + 6px); right: 0; min-width: 190px; padding: 5px; border-radius: 11px; background: var(--acm-media-raise); box-shadow: 0 0 0 1px var(--acm-media-rule2), 0 18px 40px -12px oklch(0 0 0 / .7);
  transform-origin: top right; transition: opacity .18s, scale .3s var(--acm-media-spring), translate .3s var(--acm-media-spring);
  @starting-style { opacity: 0; scale: .94; translate: 0 -4px; }
  & button { display: flex; align-items: center; gap: 9px; width: 100%; padding: 7px 9px; border-radius: 7px; text-align: left; font-size: 12.5px; color: var(--acm-media-ink); }
