/* Roles & permissions. Re-theme with --acm-roles-bg, -ink, -accent, -add and -del. */
.acm-roles {
  --acm-roles-bg: oklch(0.982 0.003 255);
  --acm-roles-ink: oklch(0.24 0.02 262);
  --acm-roles-accent: oklch(0.5 0.15 262);
  --acm-roles-add: oklch(0.58 0.13 152);
  --acm-roles-del: oklch(0.57 0.19 25);
  --acm-roles-cmp: oklch(0.72 0.14 70);

  --acm-roles-card: oklch(1 0 0);
  --acm-roles-sunk: color-mix(in oklch, var(--acm-roles-ink) 3.5%, var(--acm-roles-bg));
  --acm-roles-muted: color-mix(in oklch, var(--acm-roles-ink) 62%, var(--acm-roles-bg));
  --acm-roles-faint: color-mix(in oklch, var(--acm-roles-ink) 38%, var(--acm-roles-bg));
  --acm-roles-rule: color-mix(in oklch, var(--acm-roles-ink) 9%, transparent);
  --acm-roles-rule2: color-mix(in oklch, var(--acm-roles-ink) 16%, transparent);
  --acm-roles-hover: color-mix(in oklch, var(--acm-roles-ink) 4.5%, transparent);
  --acm-roles-tint: color-mix(in oklch, var(--acm-roles-accent) 9%, var(--acm-roles-card));
  --acm-roles-soft: color-mix(in oklab, var(--acm-roles-accent) 20%, var(--acm-roles-card));
  --acm-roles-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-roles-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-roles-h, 680px);
  container-type: inline-size;
  container-name: acm-roles;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-roles-bg);
  color: var(--acm-roles-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--acm-roles-accent);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--acm-roles-rule);
}
:where(.acm-roles) *, :where(.acm-roles) *::before, :where(.acm-roles) *::after { box-sizing: border-box; }
:where(.acm-roles) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.acm-roles) button:disabled, :where(.acm-roles) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-roles) :is(h2, h3, p, ul, ol) { margin: 0; padding: 0; }
:where(.acm-roles) :is(ul, ol) { list-style: none; }
:where(.acm-roles) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-roles) :focus-visible { outline: 2px solid var(--acm-roles-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-roles) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--acm-roles-muted); background: var(--acm-roles-card); box-shadow: inset 0 0 0 1px var(--acm-roles-rule2), 0 1px 0 var(--acm-roles-rule2); }

.acm-roles__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head head" "roles main changes";
  grid-template-columns: clamp(220px, 21cqi, 250px) minmax(0, 1fr) clamp(250px, 24cqi, 290px);
  grid-template-rows: auto minmax(0, 1fr);
}
.acm-roles[data-tab="members"] .acm-roles__app { grid-template-areas: "head head" "roles main"; grid-template-columns: clamp(220px, 21cqi, 250px) minmax(0, 1fr); }
.acm-roles[data-tab="members"] .acm-roles__changes { display: none; }

/* ---------- head ---------- */
.acm-roles__head { grid-area: head; display: flex; align-items: center; gap: 16px; padding: 0 14px 0 16px; height: 54px; border-bottom: 1px solid var(--acm-roles-rule); background: var(--acm-roles-card); }
