}
.acm-roles__ghost { display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 8px; border-radius: 6px; font-size: 12px; font-weight: 550; color: var(--acm-roles-muted); transition: background .15s, color .15s;
  & svg { width: 14px; height: 14px; }
  &:not(:disabled):hover { background: var(--acm-roles-hover); color: var(--acm-roles-ink); }
