}
.acm-roles__rolelist { overflow-y: auto; padding: 0 8px 12px; scrollbar-width: thin; }
.acm-roles__role { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 8px; padding: 9px 10px 10px; margin-bottom: 2px; border-radius: 9px; cursor: pointer; outline-offset: -2px; transition: background .15s, box-shadow .15s;
  &:hover { background: var(--acm-roles-hover); }
