  & b svg { width: 12px; height: 12px; color: var(--acm-roles-faint); }
  & .acm-roles__n { font-size: 11.5px; color: var(--acm-roles-muted); font-variant-numeric: tabular-nums; align-self: center; }
  & p { grid-column: 1 / -1; font-size: 11.5px; color: var(--acm-roles-muted); line-height: 1.35; text-wrap: pretty; }
  & .acm-roles__bar { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; margin-top: 5px; font-size: 10.5px; color: var(--acm-roles-faint); font-variant-numeric: tabular-nums; }
  & .acm-roles__bar i { flex: 1; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--acm-roles-accent) var(--p), var(--acm-roles-rule2) 0); }
  & .acm-roles__dirty { width: 7px; height: 7px; border-radius: 50%; background: var(--acm-roles-cmp); }
  &.is-all { padding: 9px 10px; }
}

/* ---------- main ---------- */
.acm-roles__main { grid-area: main; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; min-width: 0; background: var(--acm-roles-card); container: acm-roles-main / inline-size; }
.acm-roles__mtop { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; padding: 14px 16px 12px; border-bottom: 1px solid var(--acm-roles-rule);
  & h2 { display: flex; align-items: baseline; gap: 8px; margin-right: auto; font-size: clamp(15px, 1.7cqi, 18px); font-weight: 700; letter-spacing: -0.015em; text-wrap: balance; min-width: 0; }
