.acm-roles__btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 12.5px; font-weight: 600; white-space: nowrap; color: var(--acm-roles-ink); box-shadow: inset 0 0 0 1px var(--acm-roles-rule2); transition: background .15s, box-shadow .15s, translate .15s var(--acm-roles-ease), opacity .2s;
