.acm-roles__menu { position: absolute; z-index: 40; top: calc(100% + 6px); right: 0; min-width: 200px; padding: 5px; border-radius: 11px; background: var(--acm-roles-card); box-shadow: 0 0 0 1px var(--acm-roles-rule2), 0 18px 40px -14px oklch(0.25 0.03 262 / .35);
  transform-origin: top right; transition: opacity .18s, scale .3s var(--acm-roles-spring);
  @starting-style { opacity: 0; scale: .95; }
  & button { display: flex; align-items: center; gap: 9px; width: 100%; padding: 7px 9px; border-radius: 7px; font-size: 12.5px; }
