  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(v)) { ui.inviteMsg = v ? `“${v}” doesn't look like an email address.` : 'Enter an email address to invite.'; renderMembers(); const i = $('[data-f="email"]'); i.value = v; i.focus(); return; }
  if (MEMBERS.some((m) => m.email === v)) { ui.inviteMsg = `${v} has already been invited.`; renderMembers(); const i = $('[data-f="email"]'); i.value = v; i.focus(); return; }
  snap(`invite of ${v}`);
  const name = v.split('@')[0].split(/[._-]/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  const id = 'n' + Date.now().toString(36);
  MEMBERS.push({ ...M(id, name, v, ui.inviteRole, 'Invite sent just now', false), email: v, invited: true });
  ui.inviteMsg = `ok:Invite sent to ${v} as ${role(ui.inviteRole).name}.`; ui.newId = id;
  if (ui.role !== 'all' && ui.role !== ui.inviteRole) ui.role = 'all';
  renderRoles(); renderMembers(); $('[data-f="email"]')?.focus();
});
root.addEventListener('input', (ev) => {
