/* Audit log. Re-theme with --acm-audit-bg, -ink and -accent; severities are -crit, -warn,
   -note and -info and the chart, facets and rows all read them. */
.acm-audit {
  --acm-audit-bg: oklch(0.17 0.007 250);
  --acm-audit-ink: oklch(0.93 0.008 95);
  --acm-audit-accent: oklch(0.88 0.16 100);
  --acm-audit-crit: oklch(0.66 0.2 25);
  --acm-audit-warn: oklch(0.75 0.15 58);
  --acm-audit-note: oklch(0.7 0.08 235);
  --acm-audit-info: color-mix(in oklch, var(--acm-audit-ink) 42%, var(--acm-audit-bg));

  --acm-audit-panel: color-mix(in oklch, var(--acm-audit-ink) 3%, var(--acm-audit-bg));
  --acm-audit-raise: color-mix(in oklch, var(--acm-audit-ink) 7.5%, var(--acm-audit-bg));
  --acm-audit-muted: color-mix(in oklch, var(--acm-audit-ink) 60%, var(--acm-audit-bg));
  --acm-audit-faint: color-mix(in oklch, var(--acm-audit-ink) 37%, var(--acm-audit-bg));
  --acm-audit-rule: color-mix(in oklch, var(--acm-audit-ink) 8%, transparent);
  --acm-audit-rule2: color-mix(in oklch, var(--acm-audit-ink) 15%, transparent);
  --acm-audit-hover: color-mix(in oklch, var(--acm-audit-ink) 5%, transparent);
  --acm-audit-on: oklch(0.2 0.03 100);
  --acm-audit-mono: ui-monospace, Menlo, monospace;
  --acm-audit-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-audit-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-audit-h, 680px);
  container-type: inline-size;
  container-name: acm-audit;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-audit-bg);
  color: var(--acm-audit-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--acm-audit-accent);
  outline: none;
}
:where(.acm-audit) *, :where(.acm-audit) *::before, :where(.acm-audit) *::after { box-sizing: border-box; }
:where(.acm-audit) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.acm-audit) button:disabled, :where(.acm-audit) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-audit) :is(h2, h3, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
:where(.acm-audit) :is(ul, ol) { list-style: none; }
:where(.acm-audit) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-audit) :focus-visible { outline: 2px solid var(--acm-audit-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-audit) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acm-audit-mono); color: var(--acm-audit-muted); background: var(--acm-audit-raise); box-shadow: inset 0 0 0 1px var(--acm-audit-rule2); }

.acm-audit__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "views views" "facets chart" "facets list";
  grid-template-columns: clamp(200px, 20cqi, 236px) minmax(0, 1fr);
  grid-template-rows: auto auto auto minmax(0, 1fr);
}

/* ---------- head ---------- */
.acm-audit__head { grid-area: head; display: flex; align-items: center; gap: 10px; padding: 12px 14px 10px; }
.acm-audit__brand { display: flex; align-items: center; gap: 10px; min-width: 0; margin-right: 6px;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: var(--acm-audit-on); background: var(--acm-audit-accent); stroke-width: 1.9; }
  & b { display: block; font-size: 13.5px; font-weight: 700; letter-spacing: -0.01em; white-space: nowrap; }
  & span { font-size: 11px; color: var(--acm-audit-muted); white-space: nowrap; }
}
.acm-audit__q { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 7px 0 11px; border-radius: 9px; background: var(--acm-audit-panel); box-shadow: inset 0 0 0 1px var(--acm-audit-rule2); color: var(--acm-audit-faint); transition: box-shadow .2s;
  & input { flex: 1; width: 0; min-width: 0; border: 0; outline: 0; background: none; font: 500 12.5px/1 var(--acm-audit-mono); color: var(--acm-audit-ink); }
  & input::placeholder { color: var(--acm-audit-faint); font-weight: 400; }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-audit-accent); }
  &:has(input:focus) kbd { opacity: 0; }
}
.acm-audit__btn { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 8px; font-size: 12.5px; font-weight: 600; white-space: nowrap; color: var(--acm-audit-muted); box-shadow: inset 0 0 0 1px var(--acm-audit-rule2); transition: background .15s, color .15s, box-shadow .2s;
  &:not(:disabled):hover, &[aria-expanded="true"] { color: var(--acm-audit-ink); background: var(--acm-audit-hover); }
  &:disabled { opacity: .4; }
  & b { color: var(--acm-audit-accent); font-variant-numeric: tabular-nums; }
}
.acm-audit__live { & i { width: 8px; height: 8px; border-radius: 50%; background: var(--acm-audit-faint); transition: background .2s; }
  &[aria-pressed="true"] { color: var(--acm-audit-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--acm-audit-crit) 60%, transparent); background: color-mix(in oklch, var(--acm-audit-crit) 12%, transparent); }
  &[aria-pressed="true"] i { background: var(--acm-audit-crit); animation: acm-audit-blink 1.6s ease-in-out infinite; }
}
@keyframes acm-audit-blink { 50% { opacity: .25; } }
.acm-audit__filtbtn { display: none; }
.acm-audit__menuwrap { position: relative; }
.acm-audit__pop { position: absolute; z-index: 40; top: calc(100% + 8px); right: 0; width: min(460px, calc(100cqi - 28px)); padding: 12px; border-radius: 12px; background: var(--acm-audit-raise); box-shadow: 0 0 0 1px var(--acm-audit-rule2), 0 24px 50px -16px oklch(0 0 0 / .8);
  transform-origin: top right; transition: opacity .2s, scale .35s var(--acm-audit-spring);
  @starting-style { opacity: 0; scale: .96; }
  & h3 { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 12px; font-weight: 650; }
  & h3 span { color: var(--acm-audit-muted); font-weight: 500; font-variant-numeric: tabular-nums; }
  & textarea { width: 100%; height: 150px; padding: 9px 10px; border: 0; border-radius: 8px; outline: 0; resize: none; font: 11px/1.55 var(--acm-audit-mono); color: var(--acm-audit-muted); background: var(--acm-audit-bg); box-shadow: inset 0 0 0 1px var(--acm-audit-rule2); white-space: pre; }
  & div { display: flex; justify-content: flex-end; gap: 6px; margin-top: 10px; }
}
.acm-audit__btn.is-primary { color: var(--acm-audit-on); background: var(--acm-audit-accent); box-shadow: none; }
.acm-audit__btn.is-primary:hover { color: var(--acm-audit-on); background: color-mix(in oklch, var(--acm-audit-accent) 88%, white); }

/* ---------- saved views ---------- */
.acm-audit__views { grid-area: views; display: flex; gap: 6px; padding: 0 14px 10px; overflow-x: auto; scrollbar-width: none; border-bottom: 1px solid var(--acm-audit-rule);
  & button { flex: none; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 99px; font-size: 12px; font-weight: 550; color: var(--acm-audit-muted); box-shadow: inset 0 0 0 1px var(--acm-audit-rule2); transition: background .15s, color .15s; white-space: nowrap; }
  & button:hover { color: var(--acm-audit-ink); background: var(--acm-audit-hover); }
  & button[aria-selected="true"] { color: var(--acm-audit-on); background: var(--acm-audit-ink); box-shadow: none; }
  & b { font-weight: 500; opacity: .65; font-variant-numeric: tabular-nums; }
  & .acm-audit__summary { margin-left: auto; flex: none; align-self: center; font-size: 12px; color: var(--acm-audit-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .acm-audit__summary b { color: var(--acm-audit-ink); opacity: 1; font-weight: 650; }
}

/* ---------- facets ---------- */
.acm-audit__facets { grid-area: facets; min-height: 0; overflow-y: auto; padding: 12px 10px 16px; border-right: 1px solid var(--acm-audit-rule); background: var(--acm-audit-panel); scrollbar-width: thin; scrollbar-color: var(--acm-audit-rule2) transparent; }
.acm-audit__fhead { display: none; }
.acm-audit__fgroup { margin-bottom: 16px;
  & h3 { display: flex; align-items: center; justify-content: space-between; padding: 0 8px 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--acm-audit-faint); }
  & h3 button { font-size: 11px; font-weight: 550; letter-spacing: 0; text-transform: none; color: var(--acm-audit-accent); padding: 1px 5px; border-radius: 4px; }
  & h3 button:hover { background: var(--acm-audit-hover); }
}
.acm-audit__facet { position: relative; display: flex; align-items: center; gap: 9px; width: 100%; padding: 5px 8px; border-radius: 7px; font-size: 12.5px; color: var(--acm-audit-muted); transition: background .15s, color .15s; overflow: hidden;
  &::before { content: ""; position: absolute; left: 30px; right: 36px; bottom: 2px; height: 2px; border-radius: 2px; background: color-mix(in oklch, var(--c, var(--acm-audit-ink)) 45%, transparent); transform-origin: 0 50%; scale: var(--w, 0) 1; transition: scale .5s var(--acm-audit-spring); opacity: .7; }
  & > * { position: relative; }
  &:hover { color: var(--acm-audit-ink); background: var(--acm-audit-hover); }
  & .acm-audit__box { display: grid; place-items: center; width: 15px; height: 15px; border-radius: 4px; box-shadow: inset 0 0 0 1.5px var(--acm-audit-rule2); flex: none; transition: background .15s, box-shadow .15s; }
  & .acm-audit__box svg { width: 11px; height: 11px; stroke-width: 3; color: var(--acm-audit-on); opacity: 0; }
  &[aria-checked="true"] { color: var(--acm-audit-ink); }
  &[aria-checked="true"] .acm-audit__box { background: var(--c, var(--acm-audit-accent)); box-shadow: none; }
  &[aria-checked="true"] .acm-audit__box svg { opacity: 1; }
  & span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b { font: 500 11px/1 var(--acm-audit-mono); color: var(--acm-audit-faint); font-variant-numeric: tabular-nums; }
  &.is-zero { opacity: .45; }
}

/* ---------- chart ---------- */
.acm-audit__chart { grid-area: chart; padding: 12px 16px 6px; border-bottom: 1px solid var(--acm-audit-rule); }
.acm-audit__ctop { display: flex; align-items: center; gap: 12px; min-height: 26px; margin-bottom: 6px; font-size: 12px; color: var(--acm-audit-muted);
  & .acm-audit__range { display: inline-flex; align-items: center; gap: 8px; margin-right: auto; font-variant-numeric: tabular-nums; }
  & .acm-audit__range b { color: var(--acm-audit-ink); font-weight: 600; }
  & .acm-audit__leg { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; }
  & .acm-audit__leg i { width: 8px; height: 8px; border-radius: 2px; }
}
.acm-audit__clear { display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--acm-audit-accent); background: color-mix(in oklch, var(--acm-audit-accent) 12%, transparent);
  &:hover { background: color-mix(in oklch, var(--acm-audit-accent) 20%, transparent); }
  & svg { width: 12px; height: 12px; }
}
.acm-audit__plot { position: relative; height: clamp(72px, 9cqi, 104px); cursor: crosshair; touch-action: none; user-select: none; }
.acm-audit__bars { position: absolute; inset: 0; display: grid; grid-template-columns: repeat(56, 1fr); gap: 2px; align-items: end;
  background: repeating-linear-gradient(90deg, transparent 0 calc(100% / 7 - 1px), var(--acm-audit-rule) calc(100% / 7 - 1px) calc(100% / 7));
}
.acm-audit__col { position: relative; height: 100%; display: flex; flex-direction: column-reverse; transform-origin: 50% 100%; scale: 1 var(--k, 0); transition: scale .55s var(--acm-audit-spring), opacity .3s; transition-delay: calc(var(--i) * 6ms);
  & i { display: block; min-height: 0; border-radius: 1.5px; }
  & i + i { margin-bottom: 1px; }
  &.is-out { opacity: .28; }
  &.is-future { opacity: 0; }
}
.acm-audit__brush { position: absolute; top: -4px; bottom: -4px; z-index: 2; pointer-events: none; border-radius: 6px; background: color-mix(in oklch, var(--acm-audit-accent) 10%, transparent); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--acm-audit-accent) 70%, transparent);
  transition: left .25s var(--acm-audit-ease), width .25s var(--acm-audit-ease), opacity .2s;
  &[hidden] { display: block; opacity: 0; }
}
.acm-audit__plot.is-drag .acm-audit__brush { transition: none; }
.acm-audit__tip { position: absolute; z-index: 3; bottom: calc(100% + 6px); translate: -50% 0; padding: 6px 8px; border-radius: 7px; font-size: 11px; white-space: nowrap; pointer-events: none; background: var(--acm-audit-raise); box-shadow: 0 0 0 1px var(--acm-audit-rule2), 0 10px 24px -10px oklch(0 0 0 / .8); font-variant-numeric: tabular-nums;
  & b { display: block; margin-bottom: 2px; color: var(--acm-audit-ink); }
  & span { color: var(--acm-audit-muted); margin-right: 8px; }
  &[hidden] { display: none; }
}
.acm-audit__days { display: grid; grid-template-columns: repeat(7, 1fr); margin-top: 6px; font-size: 10.5px; color: var(--acm-audit-faint); font-variant-numeric: tabular-nums;
  & span { padding-left: 2px; white-space: nowrap; overflow: hidden; }
  & span.is-today { color: var(--acm-audit-accent); }
  & em { font-style: normal; }
}

/* ---------- list ---------- */
.acm-audit__list { grid-area: list; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; min-height: 0; }
.acm-audit__scroll { overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--acm-audit-rule2) transparent; }
.acm-audit__day { position: sticky; top: 0; z-index: 2; display: flex; justify-content: space-between; padding: 8px 16px 6px; font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--acm-audit-muted); background: color-mix(in oklch, var(--acm-audit-bg) 90%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--acm-audit-rule);
  & span { font: 500 11px/1 var(--acm-audit-mono); letter-spacing: 0; text-transform: none; color: var(--acm-audit-faint); }
}
.acm-audit__row { border-bottom: 1px solid var(--acm-audit-rule);
  &.is-new { animation: acm-audit-new 1.8s var(--acm-audit-ease) both; }
}
@keyframes acm-audit-new { from { background: color-mix(in oklch, var(--acm-audit-accent) 14%, transparent); } }
.acm-audit__rowbtn { display: grid; grid-template-columns: 62px 10px minmax(120px, 1.1fr) minmax(130px, 1fr) minmax(0, 1.6fr) minmax(96px, auto); align-items: center; gap: 12px; width: 100%; padding: 8px 16px; text-align: left; transition: background .15s;
  &:hover { background: var(--acm-audit-hover); }
  &[aria-expanded="true"] { background: var(--acm-audit-raise); }
  &.is-cur { box-shadow: inset 2px 0 0 var(--acm-audit-accent); }
  & time { font: 500 12px/1 var(--acm-audit-mono); color: var(--acm-audit-muted); font-variant-numeric: tabular-nums; }
  & .acm-audit__who { display: flex; align-items: center; gap: 8px; min-width: 0; font-weight: 550; }
  & .acm-audit__who span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & code { font: 500 12px/1.3 var(--acm-audit-mono); color: var(--acm-audit-ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & code em { font-style: normal; color: var(--acm-audit-faint); }
  & .acm-audit__tgt { color: var(--acm-audit-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .acm-audit__ip { font: 11.5px/1 var(--acm-audit-mono); color: var(--acm-audit-faint); text-align: right; white-space: nowrap; }
}
.acm-audit__sev { width: 8px; height: 8px; border-radius: 2px; background: var(--c);
  &[data-s="critical"] { box-shadow: 0 0 0 3px color-mix(in oklch, var(--c) 30%, transparent); }
}
.acm-audit__av { display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; flex: none; font-size: 8.5px; font-weight: 700; color: oklch(0.18 0.01 90); background: oklch(0.78 0.08 var(--h, 90));
  &.is-bot { border-radius: 5px; background: var(--acm-audit-raise); color: var(--acm-audit-muted); box-shadow: inset 0 0 0 1px var(--acm-audit-rule2); }
  &.is-bot svg { width: 12px; height: 12px; }
  &.is-anon { background: color-mix(in oklch, var(--acm-audit-crit) 25%, var(--acm-audit-bg)); color: var(--acm-audit-crit); }
}
.acm-audit__detail { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--acm-audit-ease);
  & > div { overflow: hidden; min-height: 0; }
  &.is-open { grid-template-rows: 1fr; }
}
.acm-audit__dbody { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 16px; padding: 4px 16px 14px 100px; background: var(--acm-audit-raise);
  & dl { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 5px 14px; font-size: 12px; align-content: start; }
  & dt { color: var(--acm-audit-faint); }
  & dd { font-family: var(--acm-audit-mono); font-size: 11.5px; color: var(--acm-audit-ink); overflow-wrap: anywhere; }
  & .acm-audit__acts { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 6px; }
  & .acm-audit__acts .acm-audit__btn { height: 28px; font-size: 12px; }
}
