// Audit log. EVENTS is generated once from a seed; the query, facets and brush are the only
// state. The histogram, facet counts, saved-view counts and the list are all derived from the
// same filter, so their numbers always agree.
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
