const ic = (n) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICON[n]}</svg>`;

/* ---------- seeded events ---------- */
let seed = 20261002;
const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
const pick = (a) => a[Math.floor(rnd() * a.length)];
const H = 3600e3, DAY = 24 * H;
const START = new Date(2026, 8, 26, 0, 0).getTime();
let NOW = new Date(2026, 9, 2, 10, 40, 12).getTime();
const BUCKETS = 56, BW = 3 * H;
const ACTORS = {
  mara: { name: 'Mara Quinlan', role: 'Admin', h: 30, ip: '203.0.113.24', loc: 'Lisbon, PT' },
  dev: { name: 'Dev Patel', role: 'Editor', h: 150, ip: '203.0.113.31', loc: 'Lisbon, PT' },
  sofia: { name: 'Sofia Brandt', role: 'Editor', h: 260, ip: '192.0.2.77', loc: 'Frankfurt, DE · VPN' },
  luis: { name: 'Luis Ortega', role: 'Author', h: 95, ip: '203.0.113.58', loc: 'Lisbon, PT' },
  hana: { name: 'Hana Kim', role: 'Author', h: 200, ip: '192.0.2.140', loc: 'Frankfurt, DE · VPN' },
  theo: { name: 'Theo Marsh', role: 'Security', h: 330, ip: '203.0.113.9', loc: 'Lisbon, PT' },
  'deploy-bot': { name: 'deploy-bot', role: 'Service', bot: true, ip: '10.20.0.4', loc: 'Internal' },
  'scim-sync': { name: 'scim-sync', role: 'Service', bot: true, ip: '10.20.0.9', loc: 'Internal' },
  'rate-limiter': { name: 'rate-limiter', role: 'Service', bot: true, ip: '10.20.0.2', loc: 'Internal' },
  unknown: { name: 'Unknown', role: 'Not signed in', anon: true, ip: '198.51.100.23', loc: 'Unknown network' },
