const CAT = [['auth', 'Sign-in'], ['content', 'Content'], ['access', 'People & roles'], ['security', 'Security'], ['system', 'System']];
const TPL = [
  [10, 'content', 'entry.updated', 'info', ['dev', 'sofia', 'luis', 'hana'], () => `Article · ${pick(ARTS)}`, () => { const a = 300 + Math.floor(rnd() * 900); return [['body.word_count', a, a + Math.floor(rnd() * 140) - 30]]; }],
  [4, 'content', 'entry.published', 'info', ['dev', 'sofia'], () => `Article · ${pick(ARTS)}`, () => [['status', '"approved"', '"published"']]],
