  [3, 'content', 'media.uploaded', 'info', ['luis', 'hana', 'dev'], () => `Media · screenshot-${100 + Math.floor(rnd() * 800)}.png`, () => null],
  [0.8, 'access', 'role.updated', 'notice', ['mara'], () => 'Role · Editor', () => [['permissions.redirects.delete', 'false', 'true']]],
  [0.8, 'access', 'member.invited', 'info', ['mara'], () => `Member · ${pick(['nina.berg', 'omar.haddad', 'liv.sorensen', 'kofi.boateng'])}`, () => [['role', 'null', '"Author"']]],
  [0.7, 'system', 'settings.changed', 'notice', ['mara', 'theo'], () => 'Settings · SEO defaults', () => [['seo.default_title', '"Pinecrest Help"', '"Pinecrest Help Center"']]],
  [0.5, 'system', 'export.downloaded', 'warning', ['mara', 'theo'], () => 'Export · all articles (CSV, 412 rows)', () => null],
  [0.4, 'security', 'apikey.created', 'notice', ['mara'], () => 'API key · search-indexer (read-only)', () => [['scopes', '[]', '["articles:read"]']]],
