  let rate = hr >= 9 && hr < 18 ? 1.7 : hr >= 7 && hr < 21 ? 0.35 : 0.03;
  if (weekend) rate *= 0.22;
  const n = Math.floor(rate + rnd());
  for (let i = 0; i < n; i++) EVENTS.push(fromTpl(t + Math.floor(rnd() * H)));
  if (hr === 3) EVENTS.push(mk(t + 2 * 60e3 + Math.floor(rnd() * 60e3), 'scim-sync', 'system', 'scim.synced', 'info', 'Directory · 24 members', wd === 3 ? [['members.Hana Kim.title', '"Writer"', '"Technical Writer"']] : null));
  if (!weekend && (hr === 11 || hr === 16)) EVENTS.push(mk(t + 20 * 60e3 + Math.floor(rnd() * 600e3), 'deploy-bot', 'system', 'deploy.succeeded', 'info', `Theme · help-center v3.14.${EVENTS.length % 9}`, null));
}
const at = (d, h, m, s = 0) => new Date(2026, 8 + (d < 10 ? 1 : 0), d, h, m, s).getTime();
EVENTS.push(
  mk(at(29, 13, 30, 4), 'luis', 'security', 'user.mfa_disabled', 'critical', 'Account · Luis Ortega (Author)', [['mfa.enabled', 'true', 'false']]),
  mk(at(29, 14, 2, 41), 'theo', 'security', 'policy.updated', 'notice', 'Policy · two-factor sign-in', [['mfa.required_for', '["Owner","Admin"]', '["Owner","Admin","Editor","Author"]']]),
  mk(at(29, 16, 42, 10), 'deploy-bot', 'system', 'deploy.failed', 'warning', 'Theme · help-center v3.15.0', [['build.exit_code', '0', '1']]),
  ...[[2, 14, 3], [2, 15, 1], [2, 15, 44], [2, 16, 30], [2, 17, 12], [2, 19, 2]].map(([h, m, s]) => mk(at(30, h, m, s), 'unknown', 'auth', 'user.login_failed', 'warning', 'Account · mara (Admin)', null, { why: 'wrong password' })),
  mk(at(30, 2, 19, 3), 'rate-limiter', 'security', 'ip.blocked', 'critical', 'IP · 198.51.100.23 for 24 h', [['blocklist.size', '11', '12']]),
  mk(at(30, 8, 52, 20), 'theo', 'auth', 'session.revoked', 'notice', 'Sessions · Mara Quinlan, all devices', null),
  mk(at(1, 16, 5, 36), 'mara', 'security', 'sso.config_changed', 'critical', 'SSO · SAML identity provider', [['saml.idp_cert_fingerprint', '"3F:A9:…:C1"', '"7B:22:…:0E"'], ['saml.enforce_for_all', 'false', 'true']]),
