EVENTS.sort((a, b) => b.t - a.t);
const TOTAL0 = EVENTS.length;

/* ---------- state ---------- */
const VIEWS = [['all', 'All activity', ''], ['security', 'Security', 'cat:security,auth sev:critical,warning,notice'], ['content', 'Content', 'cat:content'], ['failed', 'Failed sign-ins', 'action:user.login_failed'], ['humans', 'People only', '-is:bot']];
