/* Moderation queue. Re-theme with --acm-modq-bg, -ink and -accent; decisions read
   --acm-modq-ok, -no and -up so their colours stay consistent across buttons, tally and toasts. */
.acm-modq {
  --acm-modq-bg: oklch(0.968 0.014 82);
  --acm-modq-ink: oklch(0.26 0.03 50);
  --acm-modq-accent: oklch(0.44 0.08 205);
  --acm-modq-ok: oklch(0.56 0.12 152);
  --acm-modq-no: oklch(0.55 0.18 28);
  --acm-modq-up: oklch(0.7 0.14 68);

  --acm-modq-card: oklch(0.995 0.004 85);
  --acm-modq-sunk: color-mix(in oklch, var(--acm-modq-ink) 4%, var(--acm-modq-bg));
  --acm-modq-muted: color-mix(in oklch, var(--acm-modq-ink) 63%, var(--acm-modq-bg));
  --acm-modq-faint: color-mix(in oklch, var(--acm-modq-ink) 40%, var(--acm-modq-bg));
  --acm-modq-rule: color-mix(in oklch, var(--acm-modq-ink) 10%, transparent);
  --acm-modq-rule2: color-mix(in oklch, var(--acm-modq-ink) 18%, transparent);
  --acm-modq-hover: color-mix(in oklch, var(--acm-modq-ink) 5%, transparent);
  --acm-modq-serif: ui-serif, "Iowan Old Style", Charter, Georgia, serif;
  --acm-modq-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-modq-out: cubic-bezier(.5, 0, .75, 0);
  --acm-modq-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-modq-h, 680px);
  container-type: inline-size;
  container-name: acm-modq;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-modq-bg);
  color: var(--acm-modq-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--acm-modq-accent);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--acm-modq-rule);
}
:where(.acm-modq) *, :where(.acm-modq) *::before, :where(.acm-modq) *::after { box-sizing: border-box; }
:where(.acm-modq) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.acm-modq) button:disabled, :where(.acm-modq) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-modq) :is(h2, h3, h4, p, ul, ol, blockquote, figure, dl, dd) { margin: 0; padding: 0; }
:where(.acm-modq) :is(ul, ol) { list-style: none; }
:where(.acm-modq) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-modq) :focus-visible { outline: 2px solid var(--acm-modq-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-modq) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 650 10px/1 ui-monospace, Menlo, monospace; color: inherit; background: color-mix(in oklch, currentColor 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, currentColor 22%, transparent); }

.acm-modq__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head head" "queue stage dossier";
  grid-template-columns: clamp(250px, 25cqi, 290px) minmax(0, 1fr) clamp(236px, 23cqi, 270px);
  grid-template-rows: auto minmax(0, 1fr);
}

/* ---------- head ---------- */
.acm-modq__head { grid-area: head; display: flex; align-items: center; gap: 14px; padding: 10px 14px; border-bottom: 1px solid var(--acm-modq-rule); }
.acm-modq__brand { display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: var(--acm-modq-bg); background: var(--acm-modq-ink); }
  & b { display: block; font: 700 14px/1.15 var(--acm-modq-serif); letter-spacing: -0.005em; white-space: nowrap; }
  & span { font-size: 11px; color: var(--acm-modq-muted); white-space: nowrap; }
}
.acm-modq__tally { display: flex; align-items: center; gap: 14px; font-size: 12px; color: var(--acm-modq-muted); font-variant-numeric: tabular-nums; white-space: nowrap;
  & .acm-modq__tbar { display: flex; width: clamp(80px, 12cqi, 150px); height: 6px; border-radius: 3px; overflow: hidden; background: var(--acm-modq-rule); }
  & .acm-modq__tbar i { height: 100%; transition: flex-grow .6s var(--acm-modq-spring); }
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & span i { width: 7px; height: 7px; border-radius: 2px; }
  & b { color: var(--acm-modq-ink); font-weight: 650; }
}
.acm-modq__ghost { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 8px 0 10px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--acm-modq-muted); box-shadow: inset 0 0 0 1px var(--acm-modq-rule2); transition: background .15s, color .15s;
  &:not(:disabled):hover { color: var(--acm-modq-ink); background: var(--acm-modq-hover); }
  &:disabled { opacity: .45; }
}

/* ---------- queue ---------- */
.acm-modq__queue { grid-area: queue; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; border-right: 1px solid var(--acm-modq-rule); }
.acm-modq__tabs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; margin: 12px 12px 8px; padding: 2px; border-radius: 9px; background: var(--acm-modq-sunk); box-shadow: inset 0 0 0 1px var(--acm-modq-rule);
  & button { display: grid; justify-items: center; padding: 5px 2px 4px; border-radius: 7px; font-size: 11px; font-weight: 600; color: var(--acm-modq-muted); transition: background .15s, color .15s; }
  & button b { font-size: 16px; font-weight: 650; line-height: 1.1; color: inherit; font-variant-numeric: tabular-nums; }
  & button:hover { color: var(--acm-modq-ink); }
  & button[aria-selected="true"] { color: var(--acm-modq-ink); background: var(--acm-modq-card); box-shadow: 0 1px 3px var(--acm-modq-rule2); }
}
.acm-modq__sort { display: flex; align-items: center; justify-content: space-between; padding: 0 14px 6px; font-size: 11.5px; color: var(--acm-modq-faint);
  & div { display: flex; gap: 2px; }
  & button { padding: 3px 7px; border-radius: 6px; font-weight: 550; color: var(--acm-modq-muted); }
  & button:hover { background: var(--acm-modq-hover); color: var(--acm-modq-ink); }
  & button[aria-checked="true"] { color: var(--acm-modq-ink); background: var(--acm-modq-sunk); box-shadow: inset 0 0 0 1px var(--acm-modq-rule2); }
}
.acm-modq__items { overflow-y: auto; padding: 0 8px 12px; scrollbar-width: thin; overscroll-behavior: contain; }
.acm-modq__item { position: relative; display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 3px 10px; padding: 10px 10px 10px 8px; margin-bottom: 2px; border-radius: 10px; cursor: pointer; outline-offset: -2px; transition: background .15s, box-shadow .15s;
  &:hover { background: var(--acm-modq-hover); }
  &[aria-selected="true"] { background: var(--acm-modq-card); box-shadow: 0 0 0 1px var(--acm-modq-rule2), 0 3px 10px -6px var(--acm-modq-rule2); }
  & .acm-modq__ico { grid-row: span 2; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--acm-modq-muted); background: var(--acm-modq-sunk); }
  & .acm-modq__ico svg { width: 15px; height: 15px; }
  & .acm-modq__it { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .acm-modq__im { grid-column: 2 / -1; display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--acm-modq-muted); min-width: 0; white-space: nowrap; }
  & .acm-modq__im span { overflow: hidden; text-overflow: ellipsis; }
}
.acm-modq__risk { font: 650 11px/1 ui-monospace, Menlo, monospace; padding: 3px 5px; border-radius: 5px; align-self: start; font-variant-numeric: tabular-nums;
  color: color-mix(in oklch, var(--c) 80%, var(--acm-modq-ink)); background: color-mix(in oklch, var(--c) 14%, var(--acm-modq-card)); }
.acm-modq__sla { flex: none; display: inline-flex; align-items: center; gap: 3px; padding: 1px 6px; border-radius: 99px; font-size: 10.5px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--acm-modq-muted); background: var(--acm-modq-sunk);
  &.is-soon { color: color-mix(in oklch, var(--acm-modq-up) 70%, var(--acm-modq-ink)); background: color-mix(in oklch, var(--acm-modq-up) 18%, var(--acm-modq-card)); }
  &.is-late { color: white; background: var(--acm-modq-no); }
}
.acm-modq__done { display: grid; justify-items: center; gap: 6px; padding: 40px 16px; text-align: center; color: var(--acm-modq-muted); text-wrap: balance;
  & b { font: 600 16px/1.3 var(--acm-modq-serif); color: var(--acm-modq-ink); }
}

/* ---------- stage ---------- */
.acm-modq__stage { grid-area: stage; position: relative; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; min-height: 0; min-width: 0; background: radial-gradient(120% 70% at 50% 0%, var(--acm-modq-card), var(--acm-modq-bg) 70%); }
.acm-modq__cardwrap { position: relative; overflow-y: auto; overscroll-behavior: contain; padding: 18px clamp(14px, 2.4cqi, 28px) 24px; scrollbar-width: thin; }
.acm-modq__card { position: relative; max-width: 620px; margin: 0 auto; padding: 18px 20px 20px; border-radius: 16px; background: var(--acm-modq-card); box-shadow: 0 0 0 1px var(--acm-modq-rule), 0 1px 2px var(--acm-modq-rule), 0 18px 40px -26px oklch(0.3 0.04 50 / .35);
  transition: opacity .3s var(--acm-modq-ease), translate .45s var(--acm-modq-spring), scale .45s var(--acm-modq-spring), rotate .45s var(--acm-modq-spring);
  @starting-style { opacity: 0; translate: 0 18px; scale: .97; }
  &.is-out { pointer-events: none; transition: opacity .32s var(--acm-modq-out), translate .4s var(--acm-modq-out), rotate .4s var(--acm-modq-out), filter .4s; opacity: 0; }
  &.is-out[data-d="approve"] { translate: 60px -50px; rotate: 4deg; }
  &.is-out[data-d="remove"] { translate: -90px 30px; rotate: -6deg; filter: grayscale(1); }
  &.is-out[data-d="escalate"] { translate: 0 -80px; scale: .94; }
