  &::after { content: attr(data-stamp); position: absolute; top: 18px; right: 18px; padding: 4px 10px; border: 2px solid currentColor; border-radius: 6px; font: 800 13px/1 system-ui, sans-serif; letter-spacing: .12em; text-transform: uppercase; opacity: 0; rotate: -8deg; scale: 1.6; transition: opacity .2s, scale .3s var(--acm-modq-spring); }
