  & code { font: 11.5px ui-monospace, Menlo, monospace; }
}
.acm-modq__ctitle { font: 600 clamp(18px, 2cqi, 22px)/1.25 var(--acm-modq-serif); letter-spacing: -0.01em; text-wrap: balance; }
.acm-modq__body { margin-top: 10px; font: 400 15px/1.6 var(--acm-modq-serif); text-wrap: pretty;
  & mark { padding: 1px 2px; border-radius: 3px; color: inherit; background: color-mix(in oklch, var(--c, var(--acm-modq-no)) 18%, transparent); box-shadow: inset 0 -2px 0 color-mix(in oklch, var(--c, var(--acm-modq-no)) 70%, transparent); }
