.acm-modq__context { margin-bottom: 10px; padding: 8px 12px; border-radius: 8px; font-size: 12.5px; color: var(--acm-modq-muted); background: var(--acm-modq-sunk); box-shadow: inset 3px 0 0 var(--acm-modq-rule2); text-wrap: pretty;
