}
.acm-modq__listing { display: grid; grid-template-columns: clamp(110px, 16cqi, 150px) minmax(0, 1fr); gap: 16px; align-items: start;
  & figure { aspect-ratio: 1; border-radius: 10px; overflow: hidden; background: var(--acm-modq-sunk); }
  & figure svg { width: 100%; height: 100%; display: block; stroke: none; }
