  & p.is-them { justify-self: end; color: white; background: var(--acm-modq-accent); border-bottom-right-radius: 4px; }
  & p.is-flag { justify-self: start; border-bottom-left-radius: 4px; box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--acm-modq-no) 50%, transparent); }
