}
.acm-modq__sect { margin-top: 18px; padding-top: 14px; border-top: 1px solid var(--acm-modq-rule);
  & h4 { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--acm-modq-muted); }
  & h4 span { font-weight: 550; letter-spacing: 0; text-transform: none; color: var(--acm-modq-faint); }
}
.acm-modq__reports { display: grid; gap: 6px;
  & li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 10px; font-size: 12.5px; }
  & li b { font-weight: 650; }
  & li span { grid-column: 2; color: var(--acm-modq-muted); font-style: italic; text-wrap: pretty; }
  & li i { grid-row: span 2; padding: 2px 6px; border-radius: 5px; font: 650 11px/1.3 ui-monospace, Menlo, monospace; font-style: normal; background: var(--acm-modq-sunk); align-self: start; }
}
.acm-modq__scores { display: grid; gap: 7px;
  & li { display: grid; grid-template-columns: minmax(0, 150px) minmax(0, 1fr) 38px; align-items: center; gap: 10px; font-size: 12px; }
  & li > span:first-child { color: var(--acm-modq-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
