  & .acm-modq__meter i { display: block; height: 100%; border-radius: 3px; background: var(--c); transform-origin: 0 50%; scale: var(--v) 1; animation: acm-modq-grow .8s var(--acm-modq-ease) both; animation-delay: calc(var(--i) * 70ms + 120ms); }
  & b { font: 650 12px/1 ui-monospace, Menlo, monospace; text-align: right; font-variant-numeric: tabular-nums; }
