@keyframes acm-modq-grow { from { scale: 0 1; } }

/* ---------- decision bar ---------- */
.acm-modq__decide { position: relative; z-index: 2; padding: 10px clamp(14px, 2.4cqi, 28px) 14px; border-top: 1px solid var(--acm-modq-rule); background: color-mix(in oklch, var(--acm-modq-bg) 92%, transparent); backdrop-filter: blur(8px); }
.acm-modq__dbtns { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)) auto; gap: 8px; max-width: 620px; margin: 0 auto; }
.acm-modq__dbtn { display: flex; align-items: center; justify-content: center; gap: 8px; height: 42px; padding: 0 12px; border-radius: 11px; font-weight: 650; font-size: 13.5px; white-space: nowrap; box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--c) 45%, transparent); color: color-mix(in oklch, var(--c) 82%, var(--acm-modq-ink)); background: color-mix(in oklch, var(--c) 7%, var(--acm-modq-card));
