  &:not(:disabled):active { translate: 0 1px; }
  &[aria-expanded="true"] { color: white; background: var(--c); box-shadow: none; }
  &:disabled { opacity: .4; }
  &.is-ok { --c: var(--acm-modq-ok); }
  &.is-no { --c: var(--acm-modq-no); }
  &.is-up { --c: var(--acm-modq-up); }
  &.is-skip { --c: var(--acm-modq-faint); padding: 0 14px; }
}
.acm-modq__picker { max-width: 620px; margin: 0 auto 10px; padding: 12px; border-radius: 12px; background: var(--acm-modq-card); box-shadow: 0 0 0 1px var(--acm-modq-rule2), 0 14px 30px -18px oklch(0.3 0.04 50 / .4);
  transform-origin: 50% 100%; transition: opacity .2s, translate .35s var(--acm-modq-spring), scale .35s var(--acm-modq-spring);
  @starting-style { opacity: 0; translate: 0 10px; scale: .98; }
  & h4 { margin-bottom: 8px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--acm-modq-muted); }
  & .acm-modq__opts { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 4px; }
  & .acm-modq__opts button { display: flex; align-items: center; gap: 8px; padding: 7px 9px; border-radius: 8px; font-size: 12.5px; transition: background .15s; }
  & .acm-modq__opts button:hover { background: var(--acm-modq-hover); }
