  & textarea { width: 100%; margin-top: 8px; min-height: 52px; padding: 8px 10px; border: 0; border-radius: 8px; outline: 0; resize: none; font: inherit; color: inherit; background: var(--acm-modq-sunk); box-shadow: inset 0 0 0 1px var(--acm-modq-rule2); }
