@keyframes acm-modq-fade { from { opacity: 0; translate: 0 -3px; } }
.acm-modq__closer { display: none; }

/* ---------- toast ---------- */
.acm-modq__toast { position: absolute; left: 50%; bottom: 84px; z-index: 60; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 9px 9px 9px 14px; border-radius: 10px; font-size: 12.5px; color: var(--acm-modq-bg); background: var(--acm-modq-ink); box-shadow: 0 14px 34px -12px oklch(0.3 0.04 50 / .5);
