}

/* ---------- responsive ---------- */
@container acm-modq (max-width: 959px) {
  .acm-modq__app { grid-template-areas: "head head" "queue stage"; grid-template-columns: clamp(220px, 32cqi, 270px) minmax(0, 1fr); }
  .acm-modq__dossier { position: absolute; z-index: 30; top: 0; right: 0; bottom: 0; width: min(300px, 100%); background: var(--acm-modq-bg); box-shadow: -20px 0 40px -20px oklch(0.3 0.04 50 / .35); translate: 100% 0; visibility: hidden; transition: translate .45s var(--acm-modq-ease), visibility 0s .45s; }
  .acm-modq[data-view="dossier"] .acm-modq__dossier { translate: 0 0; visibility: visible; transition: translate .45s var(--acm-modq-ease), visibility 0s; }
  .acm-modq__closer { display: inline-flex; }
  .acm-modq__tally .acm-modq__tl { display: none; }
  .acm-modq__dbtn kbd { display: none; }
}
@container acm-modq (max-width: 759px) {
  .acm-modq__app { grid-template-areas: "head" "pane"; grid-template-columns: minmax(0, 1fr); }
