  .acm-modq[data-view="list"] .acm-modq__stage, .acm-modq:not([data-view="list"]) .acm-modq__queue { display: none; }
  .acm-modq__dossier { width: 100%; }
  .acm-modq__brand div, .acm-modq__ghost span, .acm-modq__ghost kbd { display: none; }
  .acm-modq__brand { margin-right: 0; }
