  .acm-modq__listing { grid-template-columns: minmax(0, 1fr); }
  .acm-modq__listing figure { max-width: 180px; }
  .acm-modq__scores li { grid-template-columns: minmax(0, 1fr) 70px 34px; }
}
.acm-modq__navbtn { display: none; }
@container acm-modq (max-width: 759px) { .acm-modq__navbtn { display: inline-flex; } }

@media (prefers-reduced-motion: reduce) {
  .acm-modq *, .acm-modq *::before, .acm-modq *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
  .acm-modq .acm-modq__card.is-out { translate: none; rotate: none; scale: 1; }
}

