css:
/* Navigation editor. Re-theme the editor with --acm-navtree-bg, -ink and -accent; the
   storefront preview has its own two tokens, --acm-navtree-site and --acm-navtree-brand. */
.acm-navtree {
  --acm-navtree-bg: oklch(0.205 0.006 70);
  --acm-navtree-ink: oklch(0.93 0.01 85);
  --acm-navtree-accent: oklch(0.79 0.11 232);
  --acm-navtree-bad: oklch(0.7 0.16 28);
  --acm-navtree-site: oklch(0.975 0.008 95);
  --acm-navtree-brand: oklch(0.38 0.06 155);

  --acm-navtree-panel: color-mix(in oklch, var(--acm-navtree-ink) 3.5%, var(--acm-navtree-bg));
  --acm-navtree-raise: color-mix(in oklch, var(--acm-navtree-ink) 8%, var(--acm-navtree-bg));
  --acm-navtree-muted: color-mix(in oklch, var(--acm-navtree-ink) 60%, var(--acm-navtree-bg));
  --acm-navtree-faint: color-mix(in oklch, var(--acm-navtree-ink) 37%, var(--acm-navtree-bg));
  --acm-navtree-rule: color-mix(in oklch, var(--acm-navtree-ink) 8%, transparent);
  --acm-navtree-rule2: color-mix(in oklch, var(--acm-navtree-ink) 15%, transparent);
  --acm-navtree-hover: color-mix(in oklch, var(--acm-navtree-ink) 5.5%, transparent);
  --acm-navtree-sel: color-mix(in oklch, var(--acm-navtree-accent) 15%, transparent);
  --acm-navtree-on: oklch(0.2 0.03 232);
  --acm-navtree-mono: ui-monospace, Menlo, monospace;
  --acm-navtree-indent: 22px;
  --acm-navtree-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-navtree-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-navtree-h, 680px);
  container-type: inline-size;
  container-name: acm-navtree;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-navtree-bg);
  color: var(--acm-navtree-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--acm-navtree-accent);
  outline: none;
}
:where(.acm-navtree) *, :where(.acm-navtree) *::before, :where(.acm-navtree) *::after { box-sizing: border-box; }
:where(.acm-navtree) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.acm-navtree) button:disabled, :where(.acm-navtree) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-navtree) :is(h2, h3, h4, p, ul, ol, nav) { margin: 0; padding: 0; }
:where(.acm-navtree) :is(ul, ol) { list-style: none; }
:where(.acm-navtree) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-navtree) :focus-visible { outline: 2px solid var(--acm-navtree-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-navtree) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acm-navtree-mono); color: var(--acm-navtree-muted); background: var(--acm-navtree-raise); box-shadow: inset 0 0 0 1px var(--acm-navtree-rule2); }

.acm-navtree__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "tree preview" "tree inspector";
  grid-template-columns: clamp(300px, 32cqi, 370px) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1.25fr) minmax(0, 1fr);
}

/* ---------- head ---------- */
.acm-navtree__head { grid-area: head; display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-bottom: 1px solid var(--acm-navtree-rule); }
.acm-navtree__brand { display: flex; align-items: center; gap: 10px; min-width: 0;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: var(--acm-navtree-on); background: var(--acm-navtree-accent); stroke-width: 1.8; }
  & b { display: block; font-size: 13.5px; font-weight: 700; white-space: nowrap; }
  & span { font-size: 11px; color: var(--acm-navtree-muted); white-space: nowrap; }
}
.acm-navtree__menus, .acm-navtree__panes { display: flex; gap: 2px; padding: 2px; margin-left: 8px; margin-right: auto; border-radius: 9px; background: var(--acm-navtree-panel); box-shadow: inset 0 0 0 1px var(--acm-navtree-rule);
  & button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acm-navtree-muted); white-space: nowrap; transition: background .15s, color .15s; }
  & button:hover { color: var(--acm-navtree-ink); }
  & button[aria-selected="true"] { color: var(--acm-navtree-ink); background: var(--acm-navtree-raise); box-shadow: 0 1px 2px oklch(0 0 0 / .35); }
  & b { font-weight: 500; color: var(--acm-navtree-faint); font-variant-numeric: tabular-nums; }
}
.acm-navtree__panes { display: none; }
.acm-navtree__status { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--acm-navtree-muted); white-space: nowrap; font-variant-numeric: tabular-nums;
  & i { width: 7px; height: 7px; border-radius: 50%; background: oklch(0.72 0.14 150); }
  &.is-dirty i { background: var(--acm-navtree-accent); }
  &.is-bad i, &.is-bad b { background: var(--acm-navtree-bad); color: var(--acm-navtree-bad); }
  &.is-bad b { background: none; }
}
.acm-navtree__hist { display: flex; gap: 2px;
  & button { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--acm-navtree-muted); transition: background .15s, color .15s; }
  & button:not(:disabled):hover { background: var(--acm-navtree-hover); color: var(--acm-navtree-ink); }
  & button:disabled { opacity: .35; }
}
.acm-navtree__publish { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 13px; border-radius: 8px; font-weight: 650; color: var(--acm-navtree-on); background: var(--acm-navtree-accent); transition: filter .15s, translate .15s var(--acm-navtree-ease), opacity .2s;
  &:not(:disabled):hover { filter: brightness(1.08); }
  &:not(:disabled):active { translate: 0 1px; }
  &:disabled { opacity: .4; }
}

/* ---------- tree ---------- */
.acm-navtree__treepane { grid-area: tree; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; border-right: 1px solid var(--acm-navtree-rule); background: var(--acm-navtree-panel); }
.acm-navtree__ttools { display: flex; justify-content: space-between; gap: 6px; padding: 12px 12px 8px; }
.acm-navtree__tbtn { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acm-navtree-muted); box-shadow: inset 0 0 0 1px var(--acm-navtree-rule2); transition: background .15s, color .15s;
  &:not(:disabled):hover { color: var(--acm-navtree-ink); background: var(--acm-navtree-hover); }
  &:disabled { opacity: .4; }
  &.is-danger { color: var(--acm-navtree-bad); }
}
.acm-navtree__scroll { position: relative; overflow-y: auto; overscroll-behavior: contain; padding: 0 8px 12px; scrollbar-width: thin; scrollbar-color: var(--acm-navtree-rule2) transparent; }
.acm-navtree__tree { position: relative; }
.acm-navtree__row { position: relative; display: flex; align-items: center; gap: 4px; height: 36px; padding-left: calc(var(--d) * var(--acm-navtree-indent) + 2px); padding-right: 6px; border-radius: 8px; cursor: pointer; outline-offset: -2px; transition: background .15s;
  &::before { content: ""; position: absolute; left: calc(var(--d) * var(--acm-navtree-indent) - 12px); top: 0; bottom: 50%; width: 9px; border-left: 1px solid var(--acm-navtree-rule2); border-bottom: 1px solid var(--acm-navtree-rule2); border-bottom-left-radius: 5px; opacity: min(var(--d), 1); }
  &:hover { background: var(--acm-navtree-hover); }
  &[aria-selected="true"] { background: var(--acm-navtree-sel); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--acm-navtree-accent) 35%, transparent); }
  &.is-hidden .acm-navtree__label { color: var(--acm-navtree-faint); text-decoration: line-through; text-decoration-color: var(--acm-navtree-rule2); }
  &.is-bad .acm-navtree__path { color: var(--acm-navtree-bad); }
  &.is-src { opacity: .35; }
  &.is-new { animation: acm-navtree-new 1.2s var(--acm-navtree-ease) both; }
}
@keyframes acm-navtree-new { from { background: color-mix(in oklch, var(--acm-navtree-accent) 30%, transparent); } }
.acm-navtree__grip { display: grid; place-items: center; width: 18px; height: 26px; border-radius: 5px; color: var(--acm-navtree-faint); cursor: grab; touch-action: none; opacity: .55; transition: opacity .15s, background .15s;
  & svg { width: 14px; height: 14px; fill: currentColor; stroke: none; }
  &:hover { opacity: 1; background: var(--acm-navtree-hover); }
}
.acm-navtree__row:hover .acm-navtree__grip, .acm-navtree__row[aria-selected="true"] .acm-navtree__grip { opacity: 1; }
.acm-navtree__tw { display: grid; place-items: center; width: 20px; height: 22px; border-radius: 5px; color: var(--acm-navtree-muted); flex: none;
  & svg { width: 13px; height: 13px; transition: rotate .3s var(--acm-navtree-spring); }
  &[aria-expanded="false"] svg { rotate: -90deg; }
  &:hover { background: var(--acm-navtree-hover); color: var(--acm-navtree-ink); }
}
.acm-navtree__twpad { width: 20px; flex: none; }
.acm-navtree__label { flex: 1; min-width: 0; font-weight: 550; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.acm-navtree__path { max-width: 42%; font: 11px/1 var(--acm-navtree-mono); color: var(--acm-navtree-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.acm-navtree__badge { padding: 2px 6px; border-radius: 99px; font-size: 10px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--acm-navtree-on); background: var(--acm-navtree-accent);
  &.is-sale { background: oklch(0.78 0.13 50); }
}
.acm-navtree__ra { display: none; gap: 1px;
  & button { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 6px; color: var(--acm-navtree-muted); }
  & button:hover { color: var(--acm-navtree-ink); background: var(--acm-navtree-hover); }
  & button:disabled { opacity: .3; }
  & svg { width: 14px; height: 14px; }
}
.acm-navtree__row[aria-selected="true"] .acm-navtree__ra { display: flex; }
.acm-navtree__row[aria-selected="true"] .acm-navtree__path { display: none; }
.acm-navtree__ind { position: absolute; z-index: 5; height: 2px; border-radius: 2px; background: var(--acm-navtree-accent); pointer-events: none; transition: top .12s var(--acm-navtree-ease), left .18s var(--acm-navtree-spring);
  &::before { content: ""; position: absolute; left: -4px; top: -3px; width: 8px; height: 8px; border-radius: 50%; box-shadow: inset 0 0 0 2px var(--acm-navtree-accent); background: var(--acm-navtree-panel); }
  & span { position: absolute; right: 0; top: -20px; padding: 1px 6px; border-radius: 4px; font-size: 10.5px; font-weight: 600; color: var(--acm-navtree-on); background: var(--acm-navtree-accent); white-space: nowrap; }
}
.acm-navtree__ghost { position: absolute; z-index: 6; left: 8px; right: 8px; height: 36px; display: flex; align-items: center; gap: 8px; padding: 0 10px; border-radius: 8px; pointer-events: none; font-weight: 600; background: var(--acm-navtree-raise); box-shadow: 0 0 0 1px color-mix(in oklch, var(--acm-navtree-accent) 60%, transparent), 0 14px 30px -10px oklch(0 0 0 / .7); rotate: -1.2deg; scale: 1.02;
  & small { color: var(--acm-navtree-muted); font-weight: 500; }
}
.acm-navtree.is-dragging, .acm-navtree.is-dragging * { cursor: grabbing !important; }
.acm-navtree__keys { display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 8px 14px; border-top: 1px solid var(--acm-navtree-rule); font-size: 11px; color: var(--acm-navtree-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}

/* ---------- preview ---------- */
.acm-navtree__preview { grid-area: preview; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); min-height: 0; padding: 12px 16px 0; }
