.acm-navtree__bar { position: relative; display: flex; align-items: center; gap: clamp(10px, 2cqi, 22px); height: 52px; padding: 0 18px; border-bottom: 1px solid color-mix(in oklch, var(--s-ink) 10%, transparent);
