  & .acm-navtree__grp > span { font-weight: 700; font-size: 12px; color: color-mix(in oklch, var(--s-ink) 60%, transparent); }
  & em { padding: 1px 5px; border-radius: 99px; font-style: normal; font-size: 9.5px; font-weight: 800; text-transform: uppercase; color: white; background: oklch(0.6 0.15 40); }
