.acm-navtree__hero { margin: 18px; height: 120px; border-radius: 10px; background: linear-gradient(160deg, oklch(0.75 0.06 160), oklch(0.5 0.07 165)); display: grid; align-content: end; padding: 14px 16px; color: white; font: 700 20px/1.1 ui-serif, Georgia, serif; text-wrap: balance; }
.acm-navtree__hero small { display: block; margin-top: 4px; font: 500 12px/1.3 system-ui, sans-serif; opacity: .85; }
.acm-navtree__foot { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 18px; padding: 22px 22px; margin-top: 10px; background: color-mix(in oklch, var(--acm-navtree-brand) 92%, black); color: var(--acm-navtree-site);
