}
.acm-navtree__none { display: grid; place-items: center; height: 100%; color: var(--acm-navtree-muted); text-align: center; text-wrap: balance; }

.acm-navtree__toast { position: absolute; left: 50%; bottom: 18px; z-index: 60; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 9px 9px 9px 14px; border-radius: 10px; font-size: 12.5px; color: var(--acm-navtree-ink); background: var(--acm-navtree-raise); box-shadow: 0 0 0 1px var(--acm-navtree-rule2), 0 16px 36px -12px oklch(0 0 0 / .8);
