  & button { padding: 4px 9px; border-radius: 6px; font-weight: 650; color: var(--acm-navtree-accent); }
  & button:hover { background: var(--acm-navtree-hover); }
}

/* ---------- responsive ---------- */
@container acm-navtree (max-width: 959px) {
  .acm-navtree__brand div { display: none; }
  .acm-navtree__bar { gap: 8px; padding: 0 12px; }
  .acm-navtree__bar .acm-navtree__logo { letter-spacing: .08em; font-size: 13px; margin-right: 2px; }
  .acm-navtree__top { padding: 0 6px; font-size: 12px; }
  .acm-navtree__keys { display: none; }
  .acm-navtree__app { grid-template-columns: clamp(260px, 38cqi, 330px) minmax(0, 1fr); }
}
@container acm-navtree (max-width: 759px) {
  .acm-navtree__app { grid-template-areas: "head" "pane"; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .acm-navtree__treepane, .acm-navtree__preview, .acm-navtree__inspector { grid-area: pane; border: 0; display: none; }
  .acm-navtree[data-view="tree"] .acm-navtree__treepane, .acm-navtree[data-view="item"] .acm-navtree__inspector { display: grid; }
  .acm-navtree[data-view="item"] .acm-navtree__inspector { display: block; }
  .acm-navtree[data-view="preview"] .acm-navtree__preview { display: grid; }
  .acm-navtree__head { flex-wrap: wrap; row-gap: 8px; }
  .acm-navtree__menus { order: 5; margin: 0; }
  .acm-navtree__panes { display: flex; order: 6; margin: 0 0 0 auto; }
  .acm-navtree__status span { display: none; }
  .acm-navtree__brand { margin-right: auto; }
  .acm-navtree__bar nav { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .acm-navtree *, .acm-navtree *::before, .acm-navtree *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
  .acm-navtree .acm-navtree__ghost { rotate: none; scale: 1; }
}

