const N = (id, label, type, path, parent = null, x = {}) => ({ id, label, type, path, parent, hidden: false, badge: '', newtab: false, ...x });
const MENUS = {
  main: { name: 'Main menu', items: [
    N('s1', 'Shop', 'collection', '/shop'),
    N('s2', 'Tents', 'collection', '/shop/tents', 's1'),
    N('s3', 'Sleeping bags', 'collection', '/shop/sleeping-bags', 's1'),
