    N('s7', 'Day packs', 'collection', '/shop/packs/day', 's4'),
    N('s8', 'Trekking packs', 'collection', '/shop/packs/trekking', 's4'),
    N('s5', 'Footwear', 'collection', '/shop/footwear', 's1', { badge: 'new' }),
    N('s6', 'Sale', 'collection', '/shop/sale', 's1', { badge: 'sale' }),
    N('g1', 'Guides', 'heading', ''),
    N('g2', 'Trail maps', 'page', '/guides/trail-maps', 'g1'),
    N('g3', 'Gear care', 'page', '/guides/gear-care', 'g1'),
    N('g4', 'Sizing', 'page', '/guides/sizing', 'g1'),
    N('j1', 'Journal', 'page', '/journal'),
    N('a1', 'About', 'page', '/about'),
    N('a2', 'Our story', 'page', '/about/story', 'a1'),
    N('a3', 'Stores', 'page', '/stores', 'a1'),
    N('a4', 'Careers', 'page', '/careers', 'a1', { hidden: true }),
    N('h1', 'Help', 'page', '/help'),
  ] },
  footer: { name: 'Footer', items: [
    N('f1', 'Shop', 'heading', ''),
    N('f2', 'Tents', 'collection', '/shop/tents', 'f1'), N('f3', 'Packs', 'collection', '/shop/packs', 'f1'), N('f4', 'Gift cards', 'page', '/gift-cards', 'f1'),
    N('f5', 'Company', 'heading', ''),
    N('f6', 'Our story', 'page', '/about/story', 'f5'), N('f7', 'Careers', 'page', '/careers', 'f5'), N('f8', 'Press', 'page', '/press', 'f5'),
    N('f9', 'Support', 'heading', ''),
    N('f10', 'Shipping', 'page', '/help/shipping', 'f9'), N('f11', 'Returns', 'page', '/help/returns', 'f9'), N('f12', 'Warranty', 'page', '/help/warranty', 'f9'), N('f13', 'Contact', 'page', '/contact', 'f9'),
