  if (!x.label.trim()) return 'Give it a label';
  if (x.type === 'heading') return '';
  if (x.type === 'external') return /^https:\/\/[^\s/]+\.[^\s]{2,}/.test(x.path) ? '' : 'External links must start with https://';
  if (!/^\/[a-z0-9\-/]*$/.test(x.path)) return 'Paths start with / and use lowercase letters, numbers and hyphens';
