  if (mod && k.toLowerCase() === 'z' && !typing) { ev.preventDefault(); ev.shiftKey ? restore(redo, undo) : restore(undo, redo); return; }
  if (typing) { if (k === 'Enter' || k === 'Escape') { ev.preventDefault(); $(`.acm-navtree__row[data-id="${ui.sel}"]`)?.focus(); } return; }
  if (k === 'Escape') { if (ui.open) { ui.open = null; renderPreview(); } return; }
  const row = t.closest('[role=treeitem]'); if (!row) { if (k.toLowerCase() === 'n' && !mod) { ev.preventDefault(); addItem(null, null); } return; }
  const id = row.dataset.id, fl = flat(), i = fl.findIndex((r) => r.it.id === id);
  if (ev.altKey && (k === 'ArrowUp' || k === 'ArrowDown')) { ev.preventDefault(); return moveSibling(id, k === 'ArrowUp' ? -1 : 1); }
  switch (k) {
    case 'ArrowDown': ev.preventDefault(); if (fl[i + 1]) select(fl[i + 1].it.id, true); return;
    case 'ArrowUp': ev.preventDefault(); if (fl[i - 1]) select(fl[i - 1].it.id, true); return;
    case 'ArrowRight': ev.preventDefault(); if (kids(id).length && ui.collapsed.has(id)) { ui.collapsed.delete(id); renderTree(); renderHead(); $(`.acm-navtree__row[data-id="${id}"]`)?.focus(); } else if (kids(id).length) select(kids(id)[0].id, true); return;
    case 'ArrowLeft': ev.preventDefault(); if (kids(id).length && !ui.collapsed.has(id)) { ui.collapsed.add(id); renderTree(); renderHead(); $(`.acm-navtree__row[data-id="${id}"]`)?.focus(); } else if (byId(id).parent) select(byId(id).parent, true); return;
    case 'Tab': ev.preventDefault(); return ev.shiftKey ? outdent(id) : indent(id);
    case 'Enter': ev.preventDefault(); root.dataset.view = 'item'; syncPanes(); $('[data-f="label"]')?.focus(); return;
    case 'Delete': case 'Backspace': ev.preventDefault(); return removeItem(id);
    case 'n': case 'N': if (!mod) { ev.preventDefault(); addItem(byId(id).parent, id); } return;
  }
});

renderAll();

css:
/* Redirect manager. Re-theme with --acm-redirects-bg, -ink and -accent; issue colours are
   -chain, -loop, -shadow and -dead. */
.acm-redirects {
  --acm-redirects-bg: oklch(0.205 0.018 172);
  --acm-redirects-ink: oklch(0.94 0.012 150);
  --acm-redirects-accent: oklch(0.86 0.13 145);
  --acm-redirects-chain: oklch(0.82 0.13 80);
  --acm-redirects-loop: oklch(0.7 0.17 25);
  --acm-redirects-shadow: oklch(0.76 0.09 295);
  --acm-redirects-dead: oklch(0.72 0.15 355);

  --acm-redirects-panel: color-mix(in oklch, var(--acm-redirects-ink) 3.5%, var(--acm-redirects-bg));
  --acm-redirects-raise: color-mix(in oklch, var(--acm-redirects-ink) 8%, var(--acm-redirects-bg));
  --acm-redirects-muted: color-mix(in oklch, var(--acm-redirects-ink) 60%, var(--acm-redirects-bg));
  --acm-redirects-faint: color-mix(in oklch, var(--acm-redirects-ink) 37%, var(--acm-redirects-bg));
  --acm-redirects-rule: color-mix(in oklch, var(--acm-redirects-ink) 8%, transparent);
  --acm-redirects-rule2: color-mix(in oklch, var(--acm-redirects-ink) 15%, transparent);
  --acm-redirects-hover: color-mix(in oklch, var(--acm-redirects-ink) 5%, transparent);
  --acm-redirects-on: oklch(0.22 0.04 160);
  --acm-redirects-mono: ui-monospace, Menlo, monospace;
  --acm-redirects-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-redirects-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-redirects-h, 680px);
  container-type: inline-size;
  container-name: acm-redirects;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-redirects-bg);
  color: var(--acm-redirects-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--acm-redirects-accent);
  outline: none;
}
:where(.acm-redirects) *, :where(.acm-redirects) *::before, :where(.acm-redirects) *::after { box-sizing: border-box; }
:where(.acm-redirects) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.acm-redirects) button:disabled, :where(.acm-redirects) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-redirects) :is(h2, h3, h4, p, ul, ol) { margin: 0; padding: 0; }
:where(.acm-redirects) :is(ul, ol) { list-style: none; }
:where(.acm-redirects) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-redirects) :focus-visible { outline: 2px solid var(--acm-redirects-accent); outline-offset: 2px; border-radius: 6px; }
:where(.acm-redirects) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acm-redirects-mono); color: var(--acm-redirects-muted); background: var(--acm-redirects-raise); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2); }

.acm-redirects__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "tester detail" "main detail";
  grid-template-columns: minmax(0, 1fr) clamp(280px, 28cqi, 330px);
  grid-template-rows: auto auto minmax(0, 1fr);
}

/* ---------- head ---------- */
.acm-redirects__head { grid-area: head; display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-bottom: 1px solid var(--acm-redirects-rule); }
.acm-redirects__brand { display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: var(--acm-redirects-on); background: var(--acm-redirects-accent); stroke-width: 1.9; }
  & b { display: block; font-size: 13.5px; font-weight: 700; white-space: nowrap; }
  & span { font-size: 11px; color: var(--acm-redirects-muted); white-space: nowrap; }
}
.acm-redirects__stats { display: flex; gap: 18px; margin-right: 8px; font-size: 12px; color: var(--acm-redirects-muted); white-space: nowrap;
  & b { display: block; font: 650 15px/1.15 var(--acm-redirects-mono); color: var(--acm-redirects-ink); font-variant-numeric: tabular-nums; }
  & .is-bad b { color: var(--acm-redirects-loop); }
}
.acm-redirects__btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 11px; border-radius: 8px; font-size: 12.5px; font-weight: 600; white-space: nowrap; color: var(--acm-redirects-muted); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2); transition: background .15s, color .15s, filter .15s, translate .15s var(--acm-redirects-ease);
  &:not(:disabled):hover, &[aria-pressed="true"] { color: var(--acm-redirects-ink); background: var(--acm-redirects-hover); }
  &:not(:disabled):active { translate: 0 1px; }
  &:disabled { opacity: .4; }
  &.is-primary { color: var(--acm-redirects-on); background: var(--acm-redirects-accent); box-shadow: none; }
  &.is-primary:not(:disabled):hover { color: var(--acm-redirects-on); background: var(--acm-redirects-accent); filter: brightness(1.07); }
  &.is-danger { color: var(--acm-redirects-loop); }
  &.is-sm { height: 26px; padding: 0 8px; font-size: 11.5px; border-radius: 6px; }
}

/* ---------- tester ---------- */
.acm-redirects__tester { grid-area: tester; padding: 14px 16px 12px; border-bottom: 1px solid var(--acm-redirects-rule); background: linear-gradient(180deg, var(--acm-redirects-panel), transparent); }
.acm-redirects__tin { display: flex; align-items: center; gap: 10px; height: 40px; padding: 0 6px 0 12px; border-radius: 10px; background: var(--acm-redirects-bg); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2); transition: box-shadow .2s;
  & > span { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--acm-redirects-faint); white-space: nowrap; }
  & input { flex: 1; width: 0; min-width: 0; border: 0; outline: 0; background: none; font: 500 14px/1 var(--acm-redirects-mono); color: var(--acm-redirects-ink); }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-redirects-accent); }
}
.acm-redirects__samples { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 8px;
  & button { padding: 2px 8px; border-radius: 99px; font: 11.5px var(--acm-redirects-mono); color: var(--acm-redirects-muted); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule); }
  & button:hover { color: var(--acm-redirects-ink); background: var(--acm-redirects-hover); }
  & button[aria-pressed="true"] { color: var(--acm-redirects-ink); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2); background: var(--acm-redirects-raise); }
}
.acm-redirects__trace { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 4px; margin-top: 12px; min-height: 30px; }
.acm-redirects__hop { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 7px; font: 500 12.5px/1 var(--acm-redirects-mono); background: var(--acm-redirects-raise); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2); white-space: nowrap;
  animation: acm-redirects-hop .4s var(--acm-redirects-ease) both; animation-delay: calc(var(--i) * 90ms);
  &.is-end-ok { color: var(--acm-redirects-on); background: var(--acm-redirects-accent); box-shadow: none; }
  &.is-end-bad { color: white; background: var(--acm-redirects-loop); box-shadow: none; }
  &.is-end-gone { color: var(--acm-redirects-ink); background: var(--acm-redirects-rule2); box-shadow: none; }
  & b { font-weight: 700; }
}
.acm-redirects__arrow { display: inline-flex; flex-direction: column; align-items: center; padding: 0 4px; font: 600 10px/1.1 var(--acm-redirects-mono); color: var(--acm-redirects-faint); white-space: nowrap;
  animation: acm-redirects-hop .4s var(--acm-redirects-ease) both; animation-delay: calc(var(--i) * 90ms + 45ms);
  & svg { width: 26px; height: 10px; stroke-width: 1.5; }
  & button { font: inherit; color: var(--acm-redirects-accent); }
  & button:hover { text-decoration: underline; }
}
@keyframes acm-redirects-hop { from { opacity: 0; translate: -6px 0; } }
.acm-redirects__verdict { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 10px; font-size: 12.5px; color: var(--acm-redirects-muted);
  & b { color: var(--acm-redirects-ink); }
  & .is-warn { color: var(--acm-redirects-chain); }
  & .is-bad { color: var(--acm-redirects-loop); }
}

/* ---------- table ---------- */
.acm-redirects__main { grid-area: main; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); min-height: 0; }
.acm-redirects__bar { display: flex; align-items: center; gap: 8px; padding: 10px 16px; }
.acm-redirects__filters { display: flex; gap: 2px; padding: 2px; margin-right: auto; border-radius: 9px; background: var(--acm-redirects-panel); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule);
  & button { display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acm-redirects-muted); white-space: nowrap; }
  & button:hover { color: var(--acm-redirects-ink); }
  & button[aria-selected="true"] { color: var(--acm-redirects-ink); background: var(--acm-redirects-raise); box-shadow: 0 1px 2px oklch(0 0 0 / .35); }
  & b { font-weight: 500; color: var(--acm-redirects-faint); font-variant-numeric: tabular-nums; }
  & .is-issue b { color: var(--acm-redirects-chain); }
}
.acm-redirects__search { display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 10px; border-radius: 8px; width: clamp(140px, 22cqi, 220px); color: var(--acm-redirects-faint); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2);
  & input { flex: 1; width: 0; min-width: 0; border: 0; outline: 0; background: none; font: 12px var(--acm-redirects-mono); color: var(--acm-redirects-ink); }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-redirects-accent); }
}
.acm-redirects__scroll { overflow-y: auto; overscroll-behavior: contain; padding: 0 8px 14px; scrollbar-width: thin; scrollbar-color: var(--acm-redirects-rule2) transparent; }
.acm-redirects__table { display: grid; grid-template-columns: 34px minmax(140px, 1.2fr) 18px minmax(140px, 1.2fr) 48px 96px 40px minmax(84px, auto); }
.acm-redirects__tr { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: center; column-gap: 10px; min-height: 44px; padding: 0 8px; border-bottom: 1px solid var(--acm-redirects-rule); border-radius: 8px; cursor: pointer; outline-offset: -2px; transition: background .15s, opacity .2s;
  &:hover { background: var(--acm-redirects-hover); }
  &[aria-selected="true"] { background: var(--acm-redirects-raise); box-shadow: inset 2px 0 0 var(--acm-redirects-accent); }
  &.is-off { opacity: .5; }
  &.is-hl { background: color-mix(in oklch, var(--acm-redirects-accent) 9%, transparent); }
  &.is-head { position: sticky; top: 0; z-index: 2; min-height: 32px; cursor: default; background: color-mix(in oklch, var(--acm-redirects-bg) 92%, transparent); backdrop-filter: blur(8px); font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--acm-redirects-faint); border-radius: 0; }
  &.is-head:hover { background: color-mix(in oklch, var(--acm-redirects-bg) 92%, transparent); }
  & > * { min-width: 0; }
}
.acm-redirects__n { font: 600 11.5px/1 var(--acm-redirects-mono); color: var(--acm-redirects-faint); font-variant-numeric: tabular-nums; }
.acm-redirects__pat { font: 500 12.5px/1.3 var(--acm-redirects-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  & i { font-style: normal; color: var(--acm-redirects-accent); }
  &.is-none { color: var(--acm-redirects-faint); font-style: italic; }
}
.acm-redirects__to { color: var(--acm-redirects-faint); }
.acm-redirects__to svg { width: 14px; height: 14px; }
.acm-redirects__code { justify-self: start; padding: 2px 6px; border-radius: 5px; font: 650 11px/1.2 var(--acm-redirects-mono); color: var(--acm-redirects-muted); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2);
  &[data-c="302"], &[data-c="307"] { color: oklch(0.8 0.08 230); }
  &[data-c="410"] { color: var(--acm-redirects-faint); text-decoration: line-through; }
}
.acm-redirects__hits { display: flex; align-items: center; gap: 8px; font: 500 12px/1 var(--acm-redirects-mono); color: var(--acm-redirects-muted); font-variant-numeric: tabular-nums;
  & svg { width: 44px; height: 16px; stroke: var(--acm-redirects-accent); stroke-width: 1.4; opacity: .85; overflow: visible; }
  & span { min-width: 34px; text-align: right; }
}
.acm-redirects__sw { position: relative; width: 30px; height: 18px; border-radius: 99px; background: var(--acm-redirects-rule2); transition: background .2s;
  &::after { content: ""; position: absolute; left: 3px; top: 3px; width: 12px; height: 12px; border-radius: 50%; background: var(--acm-redirects-ink); transition: translate .35s var(--acm-redirects-spring); }
  &[aria-checked="true"] { background: var(--acm-redirects-accent); }
  &[aria-checked="true"]::after { translate: 12px 0; background: var(--acm-redirects-on); }
}
.acm-redirects__issues { display: flex; flex-wrap: wrap; gap: 3px; }
.acm-redirects__issue { display: inline-flex; align-items: center; gap: 4px; padding: 2px 7px; border-radius: 99px; font-size: 10.5px; font-weight: 700; letter-spacing: .02em; color: var(--c); background: color-mix(in oklch, var(--c) 15%, transparent); white-space: nowrap;
  &[data-k="chain"] { --c: var(--acm-redirects-chain); }
  &[data-k="loop"] { --c: var(--acm-redirects-loop); }
  &[data-k="shadow"] { --c: var(--acm-redirects-shadow); }
  &[data-k="dead"] { --c: var(--acm-redirects-dead); }
}
.acm-redirects__ok { font-size: 11px; color: var(--acm-redirects-faint); }
.acm-redirects__empty { grid-column: 1 / -1; padding: 40px 20px; text-align: center; color: var(--acm-redirects-muted); }

/* ---------- detail ---------- */
.acm-redirects__detail { grid-area: detail; min-height: 0; overflow-y: auto; padding: 16px 16px 20px; border-left: 1px solid var(--acm-redirects-rule); background: var(--acm-redirects-panel); scrollbar-width: thin; }
.acm-redirects__dhead { display: flex; align-items: center; gap: 8px; margin-bottom: 14px;
  & h2 { margin-right: auto; font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--acm-redirects-muted); }
}
.acm-redirects__close { display: none; }
.acm-redirects__form { display: grid; gap: 12px; animation: acm-redirects-hop .3s var(--acm-redirects-ease) both; }
.acm-redirects__fld { display: grid; gap: 5px;
  & > span { display: flex; justify-content: space-between; font-size: 11px; font-weight: 650; letter-spacing: .05em; text-transform: uppercase; color: var(--acm-redirects-muted); }
  & :is(input, textarea) { width: 100%; height: 34px; padding: 0 10px; border: 0; border-radius: 8px; outline: 0; font: 500 12.5px var(--acm-redirects-mono); color: var(--acm-redirects-ink); background: var(--acm-redirects-bg); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule2); transition: box-shadow .2s; }
  & textarea { height: auto; min-height: 150px; padding: 9px 10px; line-height: 1.6; resize: vertical; white-space: pre; }
  & :is(input, textarea):focus { box-shadow: inset 0 0 0 1.5px var(--acm-redirects-accent); }
  & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--acm-redirects-loop); }
  & input:disabled { opacity: .45; }
  & small { font-size: 11.5px; color: var(--acm-redirects-faint); text-wrap: pretty; }
  & small.is-bad { color: var(--acm-redirects-loop); }
  & small.is-warn { color: var(--acm-redirects-chain); }
}
.acm-redirects__seg { display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--acm-redirects-bg); box-shadow: inset 0 0 0 1px var(--acm-redirects-rule);
  & button { flex: 1; height: 28px; border-radius: 7px; font: 650 12px/1 var(--acm-redirects-mono); color: var(--acm-redirects-muted); text-align: center; }
  & button:hover { color: var(--acm-redirects-ink); }
  & button[aria-checked="true"] { color: var(--acm-redirects-on); background: var(--acm-redirects-accent); }
}
.acm-redirects__hint { font-size: 11.5px; color: var(--acm-redirects-faint); text-wrap: pretty; }
.acm-redirects__keys { display: flex; flex-wrap: wrap; gap: 4px 12px; padding-top: 10px; border-top: 1px solid var(--acm-redirects-rule);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}
.acm-redirects__fix { display: grid; gap: 8px; padding: 11px 12px; border-radius: 10px; font-size: 12.5px; line-height: 1.45; text-wrap: pretty; color: var(--acm-redirects-ink); background: color-mix(in oklch, var(--c) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 35%, transparent);
  animation: acm-redirects-hop .35s var(--acm-redirects-ease) both;
  & b { color: var(--c); }
  & code { font: 12px var(--acm-redirects-mono); }
  & .acm-redirects__btn { justify-self: start; color: var(--acm-redirects-on); background: var(--c); box-shadow: none; }
}
.acm-redirects__row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.acm-redirects__lines { display: grid; gap: 2px; max-height: 160px; overflow-y: auto; font: 11.5px/1.5 var(--acm-redirects-mono);
  & li { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 6px; padding: 3px 6px; border-radius: 5px; }
  & li.is-ok { color: var(--acm-redirects-muted); }
  & li.is-ok i { color: var(--acm-redirects-accent); }
  & li.is-bad { color: var(--acm-redirects-loop); background: color-mix(in oklch, var(--acm-redirects-loop) 8%, transparent); }
  & i { font-style: normal; font-weight: 700; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.acm-redirects__toast { position: absolute; left: 50%; bottom: 18px; z-index: 60; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 9px 9px 9px 14px; border-radius: 10px; font-size: 12.5px; color: var(--acm-redirects-ink); background: var(--acm-redirects-raise); box-shadow: 0 0 0 1px var(--acm-redirects-rule2), 0 16px 36px -12px oklch(0 0 0 / .8);
  translate: -50% 0; transition: opacity .2s, translate .45s var(--acm-redirects-spring), visibility 0s;
  &:not(.is-on) { opacity: 0; translate: -50% 12px; visibility: hidden; transition: opacity .2s, translate .45s var(--acm-redirects-spring), visibility 0s .45s; }
  & button { padding: 4px 9px; border-radius: 6px; font-weight: 650; color: var(--acm-redirects-accent); }
  & button:hover { background: var(--acm-redirects-hover); }
}

/* ---------- responsive ---------- */
@container acm-redirects (max-width: 959px) {
  .acm-redirects__app { grid-template-areas: "head" "tester" "main"; grid-template-columns: minmax(0, 1fr); }
  .acm-redirects__detail { position: absolute; z-index: 30; top: 0; right: 0; bottom: 0; width: min(340px, 100%); box-shadow: -24px 0 48px -24px oklch(0 0 0 / .8); translate: 100% 0; visibility: hidden; transition: translate .45s var(--acm-redirects-ease), visibility 0s .45s; }
  .acm-redirects[data-view="detail"] .acm-redirects__detail { translate: 0 0; visibility: visible; transition: translate .45s var(--acm-redirects-ease), visibility 0s; }
  .acm-redirects__close { display: inline-flex; }
  .acm-redirects__stats .acm-redirects__s3 { display: none; }
}
@container acm-redirects (max-width: 759px) {
  .acm-redirects__brand div, .acm-redirects__btn span, .acm-redirects__stats { display: none; }
  .acm-redirects__detail { width: 100%; }
  .acm-redirects__table { grid-template-columns: 26px minmax(0, 1fr) auto; }
