  .acm-redirects__tr > :nth-child(1) { grid-row: 1 / span 2; }
  .acm-redirects__bar { flex-wrap: wrap; }
  .acm-redirects__search { width: 100%; order: -1; }
  .acm-redirects__filters { overflow-x: auto; scrollbar-width: none; max-width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  .acm-redirects *, .acm-redirects *::before, .acm-redirects *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
}

