let RULES = [
  R('/blog/:slug', '/journal/:slug', 301, 4210, 2, true, 'Blog renamed to Journal, March 2024'),
  R('/journal/2019/*', '/archive/2019/*', 301, 312, 40),
  R('/shop/old-*', '/shop', 302, 88, 300, true, 'Retired product line'),
  R('/journal/:slug', '/stories/:slug', 301, 2980, 1, true, 'Journal renamed to Stories, 2026'),
  R('/about-us', '/about', 301, 1540, 6),
  R('/about', '/company', 301, 22, 18, true, 'Added by the agency during the rebrand'),
  R('/company', '/about-us', 301, 19, 18),
  R('/events/2025/*', '', 410, 640, 75, true, 'Last year’s events, intentionally gone'),
  R('/authors/:name', '/people/:name', 301, 905, 9),
  R('/books/the-salt-path-2nd-ed', '/books/salt-roads', 301, 1220, 4),
  R('/books/:slug/reviews', '/books/:slug#reviews', 302, 377, 30),
  R('/newsletter', '/subscribe', 302, 1840, 3),
  R('/subscribe-now', '/subscribe', 301, 96, 600),
  R('/blog/harvest-notes', '/stories/harvest-notes', 301, 0, null, true, 'Old campaign landing page'),
  R('/catalogue.pdf', '/catalogue', 301, 210, 55),
  R('/careers/:role', '/jobs', 302, 0, null, false, 'Paused until the jobs page is back'),
  R('/podcast/*', '/listen/*', 301, 530, 12),
  R('/store-locator', '/bookshops', 301, 418, 20),
];
const PAGES = ['/', '/shop', '/shop/*', '/subscribe', '/bookshops', '/jobs', '/stories/*', '/archive/*', '/people/*', '/books/*', '/listen/*', '/company/*', '/press', '/media', '/sale'];
const SAMPLES = ['/blog/harvest-notes', '/about-us', '/catalogue.pdf', '/events/2025/spring-fair', '/journal/2019/winter-reading', '/careers/editor'];
const CODES = [301, 302, 307, 410];
const ui = { q: '', filter: 'all', sel: 'r1', mode: 'rule', test: '/blog/harvest-notes', hl: null, toastT: 0, editSnap: null, draft: { src: '', dst: '', code: 301 }, csv: '/press-kit,/media,301\n/events/:year/tickets,,410\n/shop/gift-card,/shop/gift-cards,301\nshop/sale,/sale,301\n/newsletter,/subscribe,301' };
const undo = [];

/* ---------- matching ---------- */
const CACHE = new Map();
function compile(p) {
