const num = (r) => RULES.indexOf(r) + 1;
const byId = (id) => RULES.find((r) => r.id === id);

/* ---------- render ---------- */
const pat = (s) => s ? esc(s).replace(/(:[a-z0-9_]+|\*)/gi, '<i>$1</i>') : '';
