  return `<svg viewBox="0 0 44 16" aria-hidden="true"><polyline points="${pts}"/></svg>`;
}
const lastTxt = (m) => m == null ? 'never' : m < 60 ? `${m} min ago` : m < 1440 ? `${Math.round(m / 60)} h ago` : `${Math.round(m / 1440)} d ago`;
function renderStats() {
  const bad = RULES.filter((r) => issues(r).length).length, hits = RULES.reduce((n, r) => n + r.hits, 0);
  $('.acm-redirects__stats').innerHTML = `<span><b>${RULES.length}</b>rules</span><span class="${bad ? 'is-bad' : ''}"><b>${bad}</b>with issues</span><span class="acm-redirects__s3"><b>${hits.toLocaleString('en-US')}</b>hits · 30 days</span>`;
}
function renderTester() {
  const t = trace(ui.test.trim() || '/'), box = $('.acm-redirects__tester');
