      <div class="acm-redirects__fld"><span>Response</span><div class="acm-redirects__seg" role="radiogroup" aria-label="Status code">${CODES.map((c) => `<button type="button" role="radio" data-code="${c}" aria-checked="${r.code === c}">${c}</button>`).join('')}</div></div>
      <label class="acm-redirects__fld"><span>Note</span><input data-e="note" value="${esc(r.note)}" placeholder="Why this rule exists" style="font-family:inherit"></label>
      <p class="acm-redirects__hint">${r.hits.toLocaleString('en-US')} hits in 30 days · last ${lastTxt(r.last)} · sample <code style="font-family:var(--acm-redirects-mono)">${esc(sampleOf(r.src))}</code></p>
      <div class="acm-redirects__row2"><button type="button" class="acm-redirects__btn" data-act="test-rule">Test sample</button><button type="button" class="acm-redirects__btn is-danger" data-act="delete">${ic('trash')}Delete</button></div>
      <p class="acm-redirects__hint acm-redirects__keys"><span><kbd>↑</kbd><kbd>↓</kbd> select</span><span><kbd>${MAC ? '⌥' : 'Alt'}</kbd><kbd>↑</kbd> reorder</span><span><kbd>Space</kbd> on/off</span><span><kbd>⌫</kbd> delete</span><span><kbd>N</kbd> new</span><span><kbd>${MOD}</kbd><kbd>Z</kbd> undo</span></p>
    </div>`;
}
function renderAll(animate, fresh) { renderStats(); renderBar(); renderTable(animate, fresh); renderTester(); renderDetail(); }

/* ---------- validation ---------- */
function validateDraft(d, rules = RULES) {
  const out = {};
  if (!d.src) out.src = ''; else if (!/^\/[^\s]*$/.test(d.src)) out.src = 'Sources start with / and have no spaces.'; else if (rules.some((r) => r.src === d.src)) out.src = `Already handled by rule #${rules.findIndex((r) => r.src === d.src) + 1}.`;
