}

/* ---------- actions ---------- */
function snap(label) { undo.push({ label, rules: RULES.map((r) => ({ ...r })), sel: ui.sel }); if (undo.length > 60) undo.shift(); }
function doUndo() { const u = undo.pop(); if (!u) return toast('Nothing to undo'); RULES = u.rules; ui.sel = byId(u.sel) ? u.sel : RULES[0].id; ui.mode = 'rule'; renderAll(true); toast(`Undid ${u.label}`); }
function toast(msg, withUndo) {
