/* ---------- events ---------- */
root.addEventListener('click', (ev) => {
  const el = ev.target.closest('button, [role=row][data-id]'); if (!el || !root.contains(el)) return;
  if (el.disabled || el.getAttribute('aria-disabled') === 'true') return;
  const d = el.dataset;
  if (d.toggle) { const r = byId(d.toggle); snap(`${r.on ? 'disable' : 'enable'} #${num(r)}`); r.on = !r.on; renderAll(); toast(`Rule #${num(r)} ${r.on ? 'enabled' : 'disabled'}`, true); return; }
  if (el.matches('[role=row]')) return select(d.id, true);
  if (d.sample) { ui.test = d.sample; $('[data-f="test"]').value = d.sample; renderTester(); return; }
  if (d.goto) { if (ui.filter !== 'all' && !visible().some((r) => r.id === d.goto)) { ui.filter = 'all'; renderBar(); renderTable(); } select(d.goto); $(`.acm-redirects__tr[data-id="${d.goto}"]`)?.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' }); return; }
  if (d.filter) { ui.filter = d.filter; renderBar(); renderTable(); return; }
  if (d.fix) return fix(d.fix, byId(d.rid), d.by && byId(d.by));
  if (d.move) { const r = byId(ui.sel); return move(r, RULES.indexOf(r) + +d.move); }
  if (d.view) { root.dataset.view = d.view; return; }
  if (d.code) { const r = byId(ui.sel); snap(`code change on #${num(r)}`); r.code = +d.code; if (r.code === 410) r.dst = ''; else if (!r.dst) r.dst = '/'; renderAll(); return; }
  if (d.dcode) { ui.draft.code = +d.dcode; renderDetail(); return; }
  switch (d.act) {
    case 'new': ui.mode = 'new'; ui.draft = { src: '', dst: '', code: 301 }; root.dataset.view = 'detail'; renderTable(); renderDetail(); $('[data-d="src"]')?.focus(); return;
    case 'import': ui.mode = 'import'; root.dataset.view = 'detail'; renderTable(); renderDetail(); $('[data-f="csv"]')?.focus(); return;
    case 'cancel': ui.mode = 'rule'; renderTable(); renderDetail(); return;
    case 'undo': return doUndo();
    case 'delete': { const r = byId(ui.sel), i = RULES.indexOf(r); snap(`delete of #${i + 1}`); RULES.splice(i, 1); ui.sel = (RULES[i] || RULES[i - 1] || {}).id; renderAll(true); toast(`Deleted ${r.src}`, true); return; }
    case 'test-rule': { const r = byId(ui.sel); ui.test = sampleOf(r.src); $('[data-f="test"]').value = ui.test; renderTester(); $('[data-f="test"]').focus(); return; }
    case 'do-import': {
      const ok = parseCSV(ui.csv).filter((l) => !l.err); snap(`import of ${ok.length} rules`);
      const made = ok.map((l) => R(l.src, l.code === 410 ? '' : l.dst, l.code, 0, null, true, 'Imported from CSV'));
      RULES.push(...made); ui.mode = 'rule'; ui.sel = made[0].id; renderAll(true, made[0].id);
      $(`.acm-redirects__tr[data-id="${made[0].id}"]`)?.scrollIntoView({ block: 'nearest' });
      toast(`Added ${made.length} rules as #${RULES.length - made.length + 1}–#${RULES.length}`, true); return;
    }
