    renderDetail(); const m = $('[data-dmsg]');
    const bad = $(v.src ? '[data-d="src"]' : '[data-d="dst"]'); if (bad) { bad.setAttribute('aria-invalid', 'true'); bad.focus(); }
    if (v.src) { const s = $('[data-d="src"] + small'); if (s) { s.textContent = v.src; s.className = 'is-bad'; } }
    if (v.dst && m) { m.textContent = v.dst; m.className = 'is-bad'; }
    return;
  }
  snap('new rule'); const r = R(d.src, d.code === 410 ? '' : d.dst, d.code, 0, null); RULES.push(r);
  ui.mode = 'rule'; ui.sel = r.id; ui.filter = 'all'; renderAll(true, r.id);
  $(`.acm-redirects__tr[data-id="${r.id}"]`)?.scrollIntoView({ block: 'nearest' });
  toast(`Added rule #${RULES.length}: ${r.src}`, true);
});
root.addEventListener('focusin', (ev) => { if (ev.target.dataset && ev.target.dataset.e) ui.editSnap = { done: false }; });
root.addEventListener('input', (ev) => {
  const t = ev.target, ds = t.dataset;
  if (ds.f === 'test') { ui.test = t.value; renderTester(); return; }
  if (ds.f === 'q') { ui.q = t.value; renderTable(); return; }
  if (ds.f === 'csv') { ui.csv = t.value; const pos = t.selectionStart; renderDetail(); const n = $('[data-f="csv"]'); n.focus(); n.setSelectionRange(pos, pos); return; }
  if (ds.d) {
    ui.draft[ds.d] = t.value.trim(); const v = validateDraft(ui.draft);
    const src = $('[data-d="src"]'), dst = $('[data-d="dst"]');
    src.toggleAttribute('aria-invalid', !!v.src); dst.toggleAttribute('aria-invalid', !!v.dst);
    src.nextElementSibling.textContent = v.src || ':name matches one segment, * matches the rest.'; src.nextElementSibling.className = v.src ? 'is-bad' : '';
    const m = $('[data-dmsg]'); m.textContent = v.dst || v.warn || 'Use the same :names to carry values across.'; m.className = v.dst ? 'is-bad' : v.warn ? 'is-warn' : '';
    return;
  }
  if (ds.e) {
    const r = byId(ui.sel); if (!r) return;
    if (ui.editSnap && !ui.editSnap.done) { snap(`edit of #${num(r)}`); ui.editSnap.done = true; }
    r[ds.e] = t.value; CACHE.clear();
    renderStats(); renderBar(); renderTable(); renderTester();
  }
});
root.addEventListener('focusout', (ev) => { if (ev.target.dataset && ev.target.dataset.e && ev.target.dataset.e !== 'note') { const pos = ev.relatedTarget; renderDetail(); if (pos && pos.dataset && pos.dataset.e) $(`[data-e="${pos.dataset.e}"]`)?.focus(); } });
