  if (k === ' ') { ev.preventDefault(); $(`[data-toggle="${r.id}"]`).click(); $(`.acm-redirects__tr[data-id="${r.id}"]`)?.focus(); return; }
  if (k === 'Delete' || k === 'Backspace') { ev.preventDefault(); ui.sel = r.id; $('[data-act="delete"]')?.click(); }
