/* Environment settings. Re-theme with --acm-envs-bg and --acm-envs-ink, and the three
   environment hues --acm-envs-dev, --acm-envs-stage and --acm-envs-prod (oklch hue angles).
   --acm-envs-hue is registered so switching environment animates the whole frame's tint. */
@property --acm-envs-hue { syntax: '<number>'; inherits: true; initial-value: 75; }

.acm-envs {
  --acm-envs-bg: oklch(0.985 0.003 250);
  --acm-envs-ink: oklch(0.23 0.012 260);
  --acm-envs-dev: 245;
  --acm-envs-stage: 72;
  --acm-envs-prod: 27;

  --acm-envs-hue: var(--acm-envs-stage);
  --acm-envs-c: oklch(0.6 0.15 var(--acm-envs-hue));
  --acm-envs-c-ink: oklch(0.45 0.13 var(--acm-envs-hue));
  --acm-envs-c-soft: oklch(0.96 0.035 var(--acm-envs-hue));
  --acm-envs-card: oklch(1 0 0);
  --acm-envs-sunk: color-mix(in oklch, var(--acm-envs-ink) 3.5%, var(--acm-envs-bg));
  --acm-envs-muted: color-mix(in oklch, var(--acm-envs-ink) 62%, var(--acm-envs-bg));
  --acm-envs-faint: color-mix(in oklch, var(--acm-envs-ink) 38%, var(--acm-envs-bg));
  --acm-envs-rule: color-mix(in oklch, var(--acm-envs-ink) 9%, transparent);
  --acm-envs-rule2: color-mix(in oklch, var(--acm-envs-ink) 16%, transparent);
  --acm-envs-hover: color-mix(in oklch, var(--acm-envs-ink) 4.5%, transparent);
  --acm-envs-mono: ui-monospace, Menlo, monospace;
  --acm-envs-ease: cubic-bezier(.2, .8, .2, 1);
  --acm-envs-spring: linear(0, 0.1 5%, 0.38 12%, 0.79 21%, 1.01 29%, 1.07 36%, 1.05 45%, 1.01 56%, 0.998 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--acm-envs-h, 680px);
  container-type: inline-size;
  container-name: acm-envs;
  overflow: clip;
  border-radius: 14px;
  background: var(--acm-envs-bg);
  color: var(--acm-envs-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--acm-envs-c);
  outline: none;
  box-shadow: inset 0 0 0 1px var(--acm-envs-rule), inset 0 3px 0 var(--acm-envs-c);
  transition: --acm-envs-hue .7s var(--acm-envs-ease);
}
.acm-envs[data-env="dev"] { --acm-envs-hue: var(--acm-envs-dev); }
.acm-envs[data-env="prod"] { --acm-envs-hue: var(--acm-envs-prod); }
:where(.acm-envs) *, :where(.acm-envs) *::before, :where(.acm-envs) *::after { box-sizing: border-box; }
:where(.acm-envs) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
:where(.acm-envs) button:disabled, :where(.acm-envs) button[aria-disabled="true"] { cursor: not-allowed; }
:where(.acm-envs) :is(h2, h3, h4, p, ul, ol) { margin: 0; padding: 0; }
:where(.acm-envs) :is(ul, ol) { list-style: none; }
:where(.acm-envs) svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.acm-envs) :focus-visible { outline: 2px solid var(--acm-envs-c); outline-offset: 2px; border-radius: 6px; }
:where(.acm-envs) kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 var(--acm-envs-mono); color: var(--acm-envs-muted); background: var(--acm-envs-card); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2), 0 1px 0 var(--acm-envs-rule2); }

.acm-envs__app {
  height: 100%;
  display: grid;
  grid-template-areas: "head head" "ribbon ribbon" "nav main" "nav save";
  grid-template-columns: clamp(200px, 20cqi, 236px) minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr) auto;
}

/* ---------- head ---------- */
.acm-envs__head { grid-area: head; display: flex; align-items: center; gap: 14px; padding: 13px 16px 11px; }
.acm-envs__brand { display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; color: white; background: var(--acm-envs-ink); }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -0.01em; }
  & span { font: 11px var(--acm-envs-mono); color: var(--acm-envs-muted); white-space: nowrap; }
}
.acm-envs__envs { position: relative; display: flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--acm-envs-sunk); box-shadow: inset 0 0 0 1px var(--acm-envs-rule);
  & button { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 12px; border-radius: 8px; font-weight: 600; color: var(--acm-envs-muted); white-space: nowrap; transition: color .2s; }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: oklch(0.62 0.15 var(--h)); box-shadow: 0 0 0 3px oklch(0.62 0.15 var(--h) / .18); }
  & button:hover { color: var(--acm-envs-ink); }
  & button[aria-checked="true"] { color: var(--acm-envs-ink); }
  & button b { min-width: 17px; height: 17px; padding: 0 5px; border-radius: 99px; display: inline-grid; place-items: center; font-size: 10.5px; font-weight: 700; color: white; background: oklch(0.6 0.15 var(--h)); font-variant-numeric: tabular-nums; }
  & kbd { margin-left: 2px; }
}
.acm-envs__pill { position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; border-radius: 8px; background: var(--acm-envs-card); box-shadow: 0 1px 3px var(--acm-envs-rule2), 0 0 0 1px var(--acm-envs-rule); transition: translate .45s var(--acm-envs-spring), width .45s var(--acm-envs-spring); }
.acm-envs__btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 11px; border-radius: 8px; font-size: 12.5px; font-weight: 600; white-space: nowrap; color: var(--acm-envs-ink); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2); transition: background .15s, box-shadow .15s, translate .15s var(--acm-envs-ease), opacity .2s;
  &:not(:disabled):hover { background: var(--acm-envs-hover); }
  &:not(:disabled):active { translate: 0 1px; }
  &:disabled { opacity: .42; }
  &[aria-pressed="true"] { color: var(--acm-envs-c-ink); background: var(--acm-envs-c-soft); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--acm-envs-c) 45%, transparent); }
  &.is-primary { color: white; background: var(--acm-envs-c-ink); box-shadow: none; }
  &.is-primary:not(:disabled):hover { background: color-mix(in oklch, var(--acm-envs-c-ink) 85%, black); }
  &.is-danger { color: oklch(0.52 0.18 27); }
  &.is-sm { height: 26px; padding: 0 8px; font-size: 11.5px; border-radius: 6px; }
  & kbd { margin-left: 2px; }
  &.is-primary kbd { color: white; background: color-mix(in oklch, white 18%, transparent); box-shadow: none; }
}

/* ---------- ribbon ---------- */
.acm-envs__ribbon { grid-area: ribbon; display: flex; align-items: center; gap: 10px; min-height: 34px; padding: 6px 16px; font-size: 12px; color: var(--acm-envs-c-ink); background: var(--acm-envs-c-soft); border-block: 1px solid color-mix(in oklch, var(--acm-envs-c) 25%, transparent);
  & b { font-weight: 700; letter-spacing: .06em; text-transform: uppercase; font-size: 11px; }
  & span { color: color-mix(in oklch, var(--acm-envs-c-ink) 80%, var(--acm-envs-ink)); }
  & em { margin-left: auto; font-style: normal; color: var(--acm-envs-muted); white-space: nowrap; }
}
.acm-envs[data-env="prod"] .acm-envs__ribbon { background: repeating-linear-gradient(-45deg, var(--acm-envs-c-soft) 0 12px, color-mix(in oklch, var(--acm-envs-c) 14%, var(--acm-envs-card)) 12px 24px); background-size: 34px 34px; animation: acm-envs-stripes 1.6s linear infinite; }
@keyframes acm-envs-stripes { to { background-position: 34px 0; } }

/* ---------- nav ---------- */
.acm-envs__nav { grid-area: nav; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); min-height: 0; padding: 12px 10px; border-right: 1px solid var(--acm-envs-rule); }
.acm-envs__search { display: flex; align-items: center; gap: 7px; height: 32px; margin: 0 2px 12px; padding: 0 6px 0 9px; border-radius: 8px; color: var(--acm-envs-faint); background: var(--acm-envs-card); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2);
  & input { flex: 1; width: 0; min-width: 0; border: 0; outline: 0; background: none; font: inherit; color: var(--acm-envs-ink); }
  &:has(input:focus) { box-shadow: inset 0 0 0 1.5px var(--acm-envs-c); }
  &:has(input:focus) kbd { opacity: 0; }
}
.acm-envs__secs { overflow-y: auto; display: grid; align-content: start; gap: 1px;
  & button { display: flex; align-items: center; gap: 9px; width: 100%; padding: 7px 9px; border-radius: 8px; font-weight: 550; color: var(--acm-envs-muted); transition: background .15s, color .15s; }
  & button:hover { color: var(--acm-envs-ink); background: var(--acm-envs-hover); }
  & button[aria-selected="true"] { color: var(--acm-envs-ink); background: var(--acm-envs-card); box-shadow: 0 0 0 1px var(--acm-envs-rule), 0 1px 3px var(--acm-envs-rule); }
  & button[aria-selected="true"] svg { color: var(--acm-envs-c-ink); }
  & b { margin-left: auto; min-width: 18px; height: 18px; padding: 0 5px; display: inline-grid; place-items: center; border-radius: 99px; font-size: 10.5px; font-weight: 700; color: var(--acm-envs-c-ink); background: var(--acm-envs-c-soft); font-variant-numeric: tabular-nums; }
  & b.is-pending { color: white; background: var(--acm-envs-c); }
  & .is-danger { color: oklch(0.52 0.18 27); }
}

/* ---------- main ---------- */
.acm-envs__main { grid-area: main; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 18px clamp(16px, 3cqi, 36px) 28px; scrollbar-width: thin; }
.acm-envs__sh { display: flex; align-items: baseline; gap: 10px; margin-bottom: 4px;
  & h2 { font-size: clamp(17px, 1.9cqi, 21px); font-weight: 700; letter-spacing: -0.02em; text-wrap: balance; }
  & span { font-size: 12px; color: var(--acm-envs-muted); }
}
.acm-envs__sp { margin-bottom: 14px; font-size: 12.5px; color: var(--acm-envs-muted); text-wrap: pretty; max-width: 70ch; }
.acm-envs__rows { display: grid; border-radius: 12px; background: var(--acm-envs-card); box-shadow: 0 0 0 1px var(--acm-envs-rule), 0 1px 2px var(--acm-envs-rule); }
.acm-envs__row { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) minmax(220px, 300px); gap: 6px 24px; align-items: center; padding: 14px 16px; border-top: 1px solid var(--acm-envs-rule);
  animation: acm-envs-in .45s var(--acm-envs-ease) both; animation-delay: calc(var(--i, 0) * 35ms);
  &:first-child { border-top: 0; }
  &::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--acm-envs-c); scale: 1 0; transition: scale .35s var(--acm-envs-spring); }
  &.is-over::before { scale: 1 1; }
  &.is-pending { background: color-mix(in oklch, var(--acm-envs-c) 5%, transparent); }
  &.is-pending::before { scale: 1 1; background: repeating-linear-gradient(var(--acm-envs-c) 0 4px, transparent 4px 7px); }
  & h3 { font-size: 13px; font-weight: 600; }
  & h3 code { margin-left: 6px; font: 11px var(--acm-envs-mono); color: var(--acm-envs-faint); font-weight: 400; }
  & p { font-size: 12px; color: var(--acm-envs-muted); text-wrap: pretty; }
}
@keyframes acm-envs-in { from { opacity: 0; translate: 0 6px; } }
.acm-envs__src { display: flex; align-items: center; gap: 8px; margin-top: 6px; font-size: 11.5px; color: var(--acm-envs-faint);
  & svg { width: 13px; height: 13px; }
  & .is-over { color: var(--acm-envs-c-ink); font-weight: 600; }
  & button { font-size: 11.5px; font-weight: 600; color: var(--acm-envs-c-ink); padding: 1px 5px; border-radius: 4px; }
  & button:hover { background: var(--acm-envs-c-soft); }
}
.acm-envs__ctl { display: flex; justify-content: flex-end; align-items: center; gap: 8px; min-width: 0;
  & input[type="text"], & input:not([type]) { width: 100%; height: 34px; padding: 0 10px; border: 0; border-radius: 8px; outline: 0; font: 12.5px var(--acm-envs-mono); color: var(--acm-envs-ink); background: var(--acm-envs-sunk); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2); transition: box-shadow .2s; }
  & input:focus { box-shadow: inset 0 0 0 1.5px var(--acm-envs-c); background: var(--acm-envs-card); }
  & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px oklch(0.55 0.18 27); }
  & input[type="range"] { flex: 1; min-width: 0; }
  & output { min-width: 46px; text-align: right; font: 600 13px var(--acm-envs-mono); font-variant-numeric: tabular-nums; }
  & .acm-envs__unit { font-size: 12px; color: var(--acm-envs-muted); white-space: nowrap; }
  & .acm-envs__num { width: 110px; text-align: right; }
}
.acm-envs__sw { position: relative; width: 38px; height: 22px; border-radius: 99px; background: var(--acm-envs-rule2); transition: background .25s; flex: none;
  &::after { content: ""; position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%; background: white; box-shadow: 0 1px 2px oklch(0 0 0 / .25); transition: translate .4s var(--acm-envs-spring); }
  &[aria-checked="true"] { background: var(--acm-envs-c); }
  &[aria-checked="true"]::after { translate: 16px 0; }
}
.acm-envs__seg { display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--acm-envs-sunk); box-shadow: inset 0 0 0 1px var(--acm-envs-rule);
  & button { height: 28px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--acm-envs-muted); white-space: nowrap; }
  & button:hover { color: var(--acm-envs-ink); }
  & button[aria-checked="true"] { color: var(--acm-envs-ink); background: var(--acm-envs-card); box-shadow: 0 1px 2px var(--acm-envs-rule2); }
}
.acm-envs__secret { display: flex; align-items: center; gap: 6px; width: 100%;
  & code { flex: 1; min-width: 0; height: 34px; display: flex; align-items: center; padding: 0 10px; border-radius: 8px; font: 12.5px var(--acm-envs-mono); background: var(--acm-envs-sunk); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: .02em; }
}
.acm-envs__ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--acm-envs-muted); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2); flex: none;
  &:hover { color: var(--acm-envs-ink); background: var(--acm-envs-hover); }
  &[aria-pressed="true"] { color: var(--acm-envs-c-ink); background: var(--acm-envs-c-soft); }
}
.acm-envs__danger { display: grid; gap: 10px; }
.acm-envs__dz { display: flex; align-items: center; gap: 16px; padding: 14px 16px; border-radius: 12px; background: var(--acm-envs-card); box-shadow: 0 0 0 1px color-mix(in oklch, oklch(0.55 0.18 27) 30%, transparent);
  & div { flex: 1; min-width: 0; }
  & h3 { font-size: 13px; font-weight: 600; }
  & p { font-size: 12px; color: var(--acm-envs-muted); text-wrap: pretty; }
}
.acm-envs__empty { padding: 40px 10px; text-align: center; color: var(--acm-envs-muted); text-wrap: balance; }

/* compare */
.acm-envs__cmp { display: grid; grid-template-columns: minmax(150px, 1.3fr) repeat(4, minmax(90px, 1fr)); border-radius: 12px; background: var(--acm-envs-card); box-shadow: 0 0 0 1px var(--acm-envs-rule); overflow: hidden; }
.acm-envs__crow { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; border-top: 1px solid var(--acm-envs-rule);
  animation: acm-envs-in .4s var(--acm-envs-ease) both; animation-delay: calc(var(--i, 0) * 20ms);
  &:first-child { border-top: 0; position: sticky; top: 0; }
  & > * { padding: 9px 12px; min-width: 0; font: 12px/1.4 var(--acm-envs-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & > :first-child { font: 600 12.5px/1.4 system-ui, sans-serif; }
  & .is-inh { color: var(--acm-envs-faint); }
  & .is-diff { background: color-mix(in oklch, oklch(0.62 0.15 var(--acm-envs-prod)) 9%, transparent); color: oklch(0.45 0.15 var(--acm-envs-prod)); font-weight: 600; }
  &.is-head > * { font: 700 10.5px/1.4 system-ui, sans-serif; letter-spacing: .07em; text-transform: uppercase; color: var(--acm-envs-muted); background: var(--acm-envs-sunk); }
  &.is-head i { display: inline-block; width: 7px; height: 7px; margin-right: 6px; border-radius: 50%; background: oklch(0.62 0.15 var(--h)); }
  &.is-sec > * { grid-column: 1 / -1; padding-top: 14px; font: 700 11px/1 system-ui, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: var(--acm-envs-faint); }
}
.acm-envs__ctop { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 14px;
  & p { margin-right: auto; font-size: 12.5px; color: var(--acm-envs-muted); max-width: 60ch; text-wrap: pretty; }
}

/* ---------- save bar ---------- */
.acm-envs__savebar { grid-area: save; display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--acm-envs-ease);
  & > div { overflow: clip; min-height: 0; }
  &.is-on { grid-template-rows: 1fr; }
}
.acm-envs__sbin { display: flex; align-items: center; gap: 10px; padding: 10px 16px; border-top: 1px solid color-mix(in oklch, var(--acm-envs-c) 30%, transparent); background: var(--acm-envs-c-soft);
  & span { margin-right: auto; font-size: 12.5px; color: var(--acm-envs-c-ink); }
  & b { font-weight: 700; }
}

/* ---------- modal ---------- */
.acm-envs__modal { position: absolute; z-index: 50; inset: 0; display: grid; place-items: center; padding: 16px; background: oklch(0.25 0.02 260 / .32); backdrop-filter: blur(2px);
  transition: opacity .2s; @starting-style { opacity: 0; }
  &[hidden] { display: none; }
}
.acm-envs__dlg { width: min(520px, 100%); max-height: 100%; overflow-y: auto; padding: 18px 18px 16px; border-radius: 16px; background: var(--acm-envs-card); box-shadow: 0 0 0 1px var(--acm-envs-rule), 0 30px 60px -20px oklch(0.25 0.02 260 / .45);
  transition: translate .45s var(--acm-envs-spring), scale .45s var(--acm-envs-spring), opacity .25s; @starting-style { translate: 0 14px; scale: .97; opacity: 0; }
  & h2 { display: flex; align-items: center; gap: 8px; font-size: 16px; font-weight: 700; letter-spacing: -0.01em; }
  & h2 i { width: 9px; height: 9px; border-radius: 50%; background: var(--acm-envs-c); }
  & > p { margin: 6px 0 14px; font-size: 12.5px; color: var(--acm-envs-muted); text-wrap: pretty; }
  & ul { display: grid; gap: 4px; margin-bottom: 14px; }
  & li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 10px; align-items: center; padding: 8px 10px; border-radius: 8px; background: var(--acm-envs-sunk); font-size: 12.5px; }
  & li code { font: 11.5px var(--acm-envs-mono); color: var(--acm-envs-muted); }
  & li .acm-envs__chg { grid-column: 2; font: 12px var(--acm-envs-mono); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & li.is-rev { grid-template-columns: minmax(0, 1fr) auto; }
  & li.is-rev .acm-envs__chg { grid-column: 1 / -1; }
  & li del { color: oklch(0.52 0.18 27); text-decoration-thickness: 1px; }
  & li ins { color: oklch(0.45 0.13 150); text-decoration: none; font-weight: 600; }
  & label { display: grid; gap: 6px; margin-bottom: 14px; font-size: 12.5px; color: var(--acm-envs-muted); }
  & label input { height: 36px; padding: 0 10px; border: 0; border-radius: 8px; outline: 0; font: 13px var(--acm-envs-mono); color: var(--acm-envs-ink); background: var(--acm-envs-sunk); box-shadow: inset 0 0 0 1px var(--acm-envs-rule2); }
  & label input:focus { box-shadow: inset 0 0 0 1.5px var(--acm-envs-c); }
  & .acm-envs__drow { display: flex; justify-content: flex-end; gap: 8px; }
}
.acm-envs__chk { width: 18px; height: 18px; border-radius: 5px; box-shadow: inset 0 0 0 1.5px var(--acm-envs-rule2); display: grid; place-items: center; color: white;
  & svg { width: 12px; height: 12px; stroke-width: 3; opacity: 0; }
  &[aria-checked="true"] { background: var(--acm-envs-c); box-shadow: none; }
  &[aria-checked="true"] svg { opacity: 1; }
  &[aria-disabled="true"] { opacity: .4; }
}
.acm-envs__toast { position: absolute; left: 50%; bottom: 18px; z-index: 60; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 9px 9px 9px 14px; border-radius: 10px; font-size: 12.5px; color: white; background: var(--acm-envs-ink); box-shadow: 0 14px 34px -12px oklch(0.25 0.02 260 / .5);
  translate: -50% 0; transition: opacity .2s, translate .45s var(--acm-envs-spring), visibility 0s;
  &:not(.is-on) { opacity: 0; translate: -50% 12px; visibility: hidden; transition: opacity .2s, translate .45s var(--acm-envs-spring), visibility 0s .45s; }
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--acm-envs-c); }
  & button { padding: 4px 9px; border-radius: 6px; font-weight: 650; color: oklch(0.85 0.1 var(--acm-envs-hue)); }
  & button:hover { background: color-mix(in oklch, white 12%, transparent); }
}

/* ---------- responsive ---------- */
@container acm-envs (max-width: 959px) {
  .acm-envs__envs kbd, .acm-envs__ribbon em { display: none; }
  .acm-envs__row { grid-template-columns: minmax(0, 1fr) minmax(200px, 250px); }
  .acm-envs__cmp { grid-template-columns: minmax(130px, 1.2fr) repeat(4, minmax(80px, 1fr)); }
}
@container acm-envs (max-width: 759px) {
  .acm-envs__app { grid-template-areas: "head" "ribbon" "nav" "main" "save"; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto auto minmax(0, 1fr) auto; }
  .acm-envs__nav { display: flex; gap: 8px; padding: 10px 12px; border: 0; border-bottom: 1px solid var(--acm-envs-rule); overflow-x: auto; scrollbar-width: none; }
  .acm-envs__search { flex: 0 0 150px; margin: 0; }
  .acm-envs__secs { display: flex; gap: 4px; overflow: visible;
    & button { white-space: nowrap; padding: 6px 10px; }
    & svg { display: none; }
  }
  .acm-envs__head { flex-wrap: wrap; row-gap: 10px; }
  .acm-envs__brand div, .acm-envs__cmpbtn span { display: none; }
  .acm-envs__envs { order: 3; flex: 1 1 100%; }
  .acm-envs__envs button { flex: 1; justify-content: center; padding: 0 6px; }
  .acm-envs__row { grid-template-columns: minmax(0, 1fr); }
  .acm-envs__ctl { justify-content: flex-start; }
  .acm-envs__cmp { grid-template-columns: minmax(110px, 1fr) repeat(4, minmax(64px, 1fr)); overflow-x: auto; }
  .acm-envs__dz { flex-direction: column; align-items: stretch; }
  .acm-envs__sbin { flex-wrap: wrap; row-gap: 8px; }
  .acm-envs__sbin span { flex-basis: 100%; }
  .acm-envs__sbin kbd { display: none; }
  .acm-envs__sbin .is-primary { margin-left: auto; }
}
.acm-envs__es { display: none; }
@container acm-envs (max-width: 420px) { .acm-envs__envs .acm-envs__el { display: none; } .acm-envs__envs .acm-envs__es { display: inline; } }

@media (prefers-reduced-motion: reduce) {
  .acm-envs, .acm-envs *, .acm-envs *::before, .acm-envs *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
}

