const SECS = [['general', 'General', 'Name, URL and the maintenance switch.'], ['domains', 'Domains', 'Where each environment is served, and how strictly.'], ['flags', 'Feature flags', 'Roll features out per environment. Percentages are of signed-in users.'], ['hooks', 'Webhooks', 'Events Quillmate sends to your backend.'], ['email', 'Email', 'Sender identity and safety limits.'], ['secrets', 'Secrets', 'Keys are stored encrypted and never shown in full in production.'], ['danger', 'Danger zone', 'Irreversible or high-impact actions.']];
const K = (k, sec, label, desc, type, x = {}) => ({ k, sec, label, desc, type, ...x });
const KEYS = [
  K('app.name', 'general', 'Product name', 'Shown in the browser tab and emails.', 'text'),
